"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { createClient, type User } from "@supabase/supabase-js";

type Match = { id:number; gameId:string; date:string; groupSize:number; side:string; result:string; duration:number; notes:string; createdBy?:string|null };
type Performance = { id:number; matchId:number; team:string; tracked:boolean; player:string; champion:string; role:string; kills:number; deaths:number; assists:number; cs:number; vision:number };
type AuditEvent = { id:number; matchId:number; action:"created"|"edited"|"deleted"|"restored"; actorEmail:string; changes:Record<string,{from:unknown;to:unknown}>; createdAt:string };
type UserRole = "administrator"|"moderator"|"user";
type UserProfile = { userId:string; email:string; role:UserRole };
type PendingSubmission = { id:number; submittedBy:string; submitterEmail:string; matchData:{game_id:string;match_date:string;friend_group_size:number;ally_side:string;result:string;duration_minutes:number;notes?:string}; performanceData:Array<{player:string;champion:string;role:string;kills:number;deaths:number;assists:number;cs:number;vision:number}>; captureMetadata:Record<string,unknown>; createdAt:string };
type FeedbackStatus = "Backlog"|"Accepted"|"Declined"|"In Progress"|"Review Pending"|"Complete"|"DELETED";
type FeedbackItem = { id:number; subject:string; context:string; status:FeedbackStatus; submittedBy:string; submitterEmail:string; createdAt:string; updatedAt:string };
type TrackerData = { matches:Match[]; performances:Performance[]; players:string[]; champions:string[]; roles:string[] };
type Tab = "overview" | "players" | "roles" | "insights" | "matches" | "feedback" | "review" | "audit" | "accounts" | "add";
type PlayerMatchScope = "group" | "solo" | "all";

const supabase=createClient("https://vkxbjvjyfxkrfktdbmsu.supabase.co","sb_publishable_bGA7V1Di86IiVsmYErH3iA_zEnXNLGy");

const kda = (p:Performance) => (p.kills + p.assists) / Math.max(1, p.deaths);
const pct = (n:number) => `${Math.round(n * 100)}%`;
const num = (n:number, digits=1) => Number.isFinite(n) ? n.toFixed(digits) : "—";
const durationInput = (minutes:number) => { const total=Math.round(minutes*60); return `${Math.floor(total/3600)}:${String(Math.floor(total%3600/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`; };
const roleColors:Record<string,string>={Top:'#d89b43',Jungle:'#45a56a',Mid:'#5c92d8',Bot:'#a76bd1',Support:'#d56575'};
const championIcon=(name:string)=>`./champions/${name.toLowerCase().replace(/[^a-z0-9]/g,'')}.png`;
const roleIcon=(role:string)=>`./roles/${role.toLowerCase()}.svg`;
const gamerTags:Record<string,string>={Austin:"sweetberryW","Blake D.":"Retrax","Blake G.":"Kelando",Dane:"Bishop",Jake:"Rook",Kaleb:"Tokoyami",Rachel:"Amicias",Steven:"Knada",Zach:"Valabrax"};
const playerName=(name:string)=>gamerTags[name]??name;
const scopedTrackerData=(data:TrackerData,predicate:(match:Match)=>boolean):TrackerData=>{const matches=data.matches.filter(predicate);const matchIds=new Set(matches.map(match=>match.id));return {...data,matches,performances:data.performances.filter(row=>matchIds.has(row.matchId))}};
const roleRatingWeights:Record<string,Record<string,number>>={Top:{winRate:25,kills:10,deaths:15,assists:5,kda:15,cs:25,vision:5},Jungle:{winRate:25,kills:10,deaths:15,assists:15,kda:15,cs:10,vision:10},Mid:{winRate:25,kills:15,deaths:10,assists:10,kda:15,cs:20,vision:5},Bot:{winRate:25,kills:15,deaths:15,assists:5,kda:15,cs:20,vision:5},Support:{winRate:25,kills:5,deaths:15,assists:20,kda:15,cs:0,vision:20}};

function calculateRoleRatings(data:TrackerData,role:string) {
  const metricKeys=["kills","deaths","assists","kda","cs","vision"] as const;
  const rows=data.players.map(player=>{const performances=data.performances.filter(p=>p.tracked&&p.player===player&&p.role===role);const games=performances.length;const wins=performances.filter(p=>data.matches.find(m=>m.id===p.matchId)?.result==="Win").length;const totals=performances.reduce((a,p)=>({kills:a.kills+p.kills,deaths:a.deaths+p.deaths,assists:a.assists+p.assists,cs:a.cs+p.cs,vision:a.vision+p.vision,minutes:a.minutes+(data.matches.find(m=>m.id===p.matchId)?.duration??0)}),{kills:0,deaths:0,assists:0,cs:0,vision:0,minutes:0});return {player,games,wins,winRate:wins/Math.max(1,games),kills:totals.kills/Math.max(1,games),deaths:totals.deaths/Math.max(1,games),assists:totals.assists/Math.max(1,games),kda:(totals.kills+totals.assists)/Math.max(1,totals.deaths),cs:totals.cs/Math.max(1,totals.minutes),vision:totals.vision/Math.max(1,totals.minutes)}}).filter(row=>row.games>0);
  const means=Object.fromEntries(metricKeys.map(key=>[key,rows.reduce((sum,row)=>sum+row[key],0)/Math.max(1,rows.length)])) as Record<typeof metricKeys[number],number>;
  const adjusted=rows.map(row=>{const trust=row.games/(row.games+5);return {...row,metrics:{winRate:(row.wins+2)/(row.games+4),...Object.fromEntries(metricKeys.map(key=>[key,trust*row[key]+(1-trust)*means[key]]))} as Record<"winRate"|typeof metricKeys[number],number>}});
  const percentile=(value:number,key:"winRate"|typeof metricKeys[number])=>{if(adjusted.length<=1)return 50;const values=adjusted.map(row=>row.metrics[key]);const below=values.filter(other=>key==="deaths"?other>value:other<value).length;const tied=values.filter(other=>other===value).length;return 100*(below+Math.max(0,tied-1)/2)/(values.length-1)};
  const weights=roleRatingWeights[role]??roleRatingWeights.Top;
  return new Map(adjusted.map(row=>{const components=Object.fromEntries((["winRate",...metricKeys] as const).map(key=>[key,percentile(row.metrics[key],key)])) as Record<"winRate"|typeof metricKeys[number],number>;return [row.player,Object.entries(weights).reduce((sum,[key,weight])=>sum+components[key as keyof typeof components]*weight/100,0)]}));
}

function RoleLabel({role}:{role:string}) {
  return <span className="role-label"><img src={roleIcon(role)} alt=""/>{role}</span>;
}

function Stat({label,value,detail,tone}:{label:string;value:string;detail:string;tone?:string}) {
  return <article className={`stat ${tone ?? ""}`}><div className="stat-label">{label}</div><strong>{value}</strong><span>{detail}</span></article>;
}

function RolesArchive({data}:{data:TrackerData}) {
  type RoleSortKey="player"|"roleGames"|"roleWinRate"|"avgKills"|"avgDeaths"|"avgAssists"|"avgKda"|"csPerMinute"|"visionPerMinute"|"rating";
  const [archiveRole,setArchiveRole]=useState("Top");
  const [expandedPlayer,setExpandedPlayer]=useState<string|null>(null);
  const [roleSort,setRoleSort]=useState<RoleSortKey>("roleGames");
  const [roleSortDirection,setRoleSortDirection]=useState<"desc"|"asc">("desc");
  const [ratingDocsOpen,setRatingDocsOpen]=useState(false);
  const ratingDocsRef=useRef<HTMLDetailsElement>(null);
  const revealRatingDocs=()=>{setRatingDocsOpen(true);requestAnimationFrame(()=>ratingDocsRef.current?.scrollIntoView({behavior:"smooth",block:"center"}));requestAnimationFrame(()=>ratingDocsRef.current?.focus({preventScroll:true}))};
  const roleOrder=["Top","Jungle","Mid","Bot","Support"].filter(role=>data.roles.includes(role));
  const weights=roleRatingWeights;
  const rawRankings=data.players.map(player=>{
    const roleRows=data.performances.filter(p=>p.tracked&&p.player===player&&p.role===archiveRole);
    const championCounts=roleRows.reduce((acc,p)=>(acc[p.champion]=(acc[p.champion]||0)+1,acc),{} as Record<string,number>);
    const totals=roleRows.reduce((acc,p)=>({kills:acc.kills+p.kills,deaths:acc.deaths+p.deaths,assists:acc.assists+p.assists,cs:acc.cs+p.cs,vision:acc.vision+p.vision,minutes:acc.minutes+(data.matches.find(m=>m.id===p.matchId)?.duration??0)}),{kills:0,deaths:0,assists:0,cs:0,vision:0,minutes:0});
    const champions=Object.entries(championCounts).map(([champion,games])=>{
      const championRows=roleRows.filter(p=>p.champion===champion);
      const wins=championRows.filter(p=>data.matches.find(m=>m.id===p.matchId)?.result==="Win").length;
      const championTotals=championRows.reduce((acc,p)=>({kills:acc.kills+p.kills,deaths:acc.deaths+p.deaths,assists:acc.assists+p.assists,cs:acc.cs+p.cs,vision:acc.vision+p.vision,minutes:acc.minutes+(data.matches.find(m=>m.id===p.matchId)?.duration??0)}),{kills:0,deaths:0,assists:0,cs:0,vision:0,minutes:0});
      return {champion,games,winRate:wins/Math.max(1,games),kda:(championTotals.kills+championTotals.assists)/Math.max(1,championTotals.deaths),csPerMinute:championTotals.cs/Math.max(1,championTotals.minutes),visionPerMinute:championTotals.vision/Math.max(1,championTotals.minutes)};
    }).sort((a,b)=>b.games-a.games||a.champion.localeCompare(b.champion)).slice(0,3);
    const roleGames=roleRows.length;
    const roleWins=roleRows.filter(p=>data.matches.find(m=>m.id===p.matchId)?.result==="Win").length;
    return {player,roleGames,roleWins,roleWinRate:roleWins/Math.max(1,roleGames),avgKills:totals.kills/Math.max(1,roleGames),avgDeaths:totals.deaths/Math.max(1,roleGames),avgAssists:totals.assists/Math.max(1,roleGames),avgKda:(totals.kills+totals.assists)/Math.max(1,totals.deaths),csPerMinute:totals.cs/Math.max(1,totals.minutes),visionPerMinute:totals.vision/Math.max(1,totals.minutes),champions};
  }).filter(row=>row.roleGames>0);
  const metricKeys=["kills","deaths","assists","kda","cs","vision"] as const;
  const field={kills:"avgKills",deaths:"avgDeaths",assists:"avgAssists",kda:"avgKda",cs:"csPerMinute",vision:"visionPerMinute"} as const;
  const roleMeans=Object.fromEntries(metricKeys.map(key=>[key,rawRankings.reduce((sum,row)=>sum+row[field[key]],0)/Math.max(1,rawRankings.length)])) as Record<typeof metricKeys[number],number>;
  const adjusted=rawRankings.map(row=>{const trust=row.roleGames/(row.roleGames+5);return {...row,adjusted:{winRate:(row.roleWins+2)/(row.roleGames+4),...Object.fromEntries(metricKeys.map(key=>[key,trust*row[field[key]]+(1-trust)*roleMeans[key]]))} as Record<"winRate"|typeof metricKeys[number],number>}});
  const percentile=(value:number,key:"winRate"|typeof metricKeys[number])=>{if(adjusted.length<=1)return 50;const values=adjusted.map(row=>row.adjusted[key]);const below=values.filter(other=>key==="deaths"?other>value:other<value).length;const tied=values.filter(other=>other===value).length;return 100*(below+Math.max(0,tied-1)/2)/(values.length-1)};
  const rankings=adjusted.map(row=>{const components=Object.fromEntries((["winRate",...metricKeys] as const).map(key=>[key,percentile(row.adjusted[key],key)])) as Record<"winRate"|typeof metricKeys[number],number>;const roleWeights=weights[archiveRole]??weights.Top;const rating=Object.entries(roleWeights).reduce((sum,[key,weight])=>sum+components[key as keyof typeof components]*weight/100,0);return {...row,rating};}).sort((a,b)=>{const comparison=roleSort==="player"?playerName(a.player).localeCompare(playerName(b.player)):a[roleSort]-b[roleSort];return (roleSortDirection==="desc"?-comparison:comparison)||b.roleGames-a.roleGames||playerName(a.player).localeCompare(playerName(b.player))});
  const sortBy=(key:RoleSortKey)=>{if(roleSort===key)setRoleSortDirection(direction=>direction==="desc"?"asc":"desc");else{setRoleSort(key);setRoleSortDirection("desc")}};
  const SortHeading=({column,label}:{column:RoleSortKey;label:string})=><button type="button" className={roleSort===column?'active':''} aria-label={`Sort by ${label} ${roleSort===column&&roleSortDirection==="desc"?'ascending':'descending'}`} onClick={()=>sortBy(column)}><span>{label}</span><i aria-hidden="true">{roleSort===column?(roleSortDirection==="desc"?'▼':'▲'):'↕'}</i></button>;

  return <>
    <div className="role-archive-tabs" role="tablist" aria-label="Role archive">{roleOrder.map(role=><button type="button" role="tab" aria-selected={archiveRole===role} className={archiveRole===role?'active':''} onClick={()=>{setArchiveRole(role);setExpandedPlayer(null)}} key={role}><RoleLabel role={role}/></button>)}</div>
    <section className="panel role-rankings"><div className="panel-head"><div><p>ROLE ARCHIVE</p><h3><RoleLabel role={archiveRole}/> player activity</h3></div></div>
      <details ref={ratingDocsRef} tabIndex={-1} open={ratingDocsOpen} onToggle={e=>setRatingDocsOpen(e.currentTarget.open)} className="rating-docs"><summary><span>How the Role Performance Rating works <em>BETA FEATURE</em></span><i>Methodology and {archiveRole} weights</i></summary><div><p>This experimental 0–100 rating compares players only with other players in the selected role. Each metric becomes a role-relative percentile; deaths are inverted so fewer deaths score higher. Small samples are pulled toward the role average, and win rate starts with a 2–2 prior. It is not a definitive measure of skill and is subject to change as the archive grows.</p><div className="rating-formula"><b>{archiveRole} weights</b>{Object.entries(weights[archiveRole]??weights.Top).filter(([,value])=>value>0).map(([key,value])=><span key={key}>{key==="winRate"?"Win rate":key==="cs"?"CS / min":key==="vision"?"Vision / min":key[0].toUpperCase()+key.slice(1)} <strong>{value}%</strong></span>)}</div><small>Sample adjustment: player metric × games/(games+5) + role average × 5/(games+5). Adjusted win rate: (wins+2)/(games+4).</small></div></details>
      <div className="role-ranking-head"><span>#</span><SortHeading column="player" label="PLAYER"/><SortHeading column="roleGames" label="ROLE MATCHES"/><SortHeading column="roleWinRate" label="ROLE WIN RATE"/><SortHeading column="avgKills" label="AVG KILLS"/><SortHeading column="avgDeaths" label="AVG DEATHS"/><SortHeading column="avgAssists" label="AVG ASSISTS"/><SortHeading column="avgKda" label="AVG KDA"/><SortHeading column="csPerMinute" label="AVG CS / MIN"/><SortHeading column="visionPerMinute" label="AVG VISION / MIN"/><span className="rating-heading"><SortHeading column="rating" label="RATING"/><button className="rating-info-button" type="button" aria-label="Open experimental rating methodology" data-tip="Experimental feature — subject to change" onClick={revealRatingDocs}>i</button></span><span></span></div>
      <div className="role-ranking-list">{rankings.map((row,index)=>{const isOpen=expandedPlayer===row.player;return <article className={isOpen?'expanded':''} key={row.player}><button className="role-player-summary" type="button" aria-expanded={isOpen} onClick={()=>setExpandedPlayer(isOpen?null:row.player)}><span className="role-rank">{String(index+1).padStart(2,'0')}</span><b>{playerName(row.player)}</b><div><small>ROLE MATCHES</small><strong>{row.roleGames}</strong></div><div><small>ROLE WIN RATE</small><strong>{pct(row.roleWinRate)}</strong></div><div><small>AVG KILLS</small><strong>{num(row.avgKills,2)}</strong></div><div><small>AVG DEATHS</small><strong>{num(row.avgDeaths,2)}</strong></div><div><small>AVG ASSISTS</small><strong>{num(row.avgAssists,2)}</strong></div><div><small>AVG KDA</small><strong>{num(row.avgKda,2)}</strong></div><div><small>AVG CS / MIN</small><strong>{num(row.csPerMinute,2)}</strong></div><div><small>AVG VISION / MIN</small><strong>{num(row.visionPerMinute,2)}</strong></div><div className="rating-value"><small>RATING</small><strong>{Math.round(row.rating)}</strong><span>/ 100</span></div><i>{isOpen?'−':'+'}</i></button>{isOpen&&<div className="role-champion-breakdown"><div className="role-champion-head"><div><p>CHAMPION BREAKDOWN</p><h4>{playerName(row.player)}’s top {row.champions.length} {archiveRole} champions</h4></div><span>Sorted by champion matches</span></div><div className="role-champion-grid">{row.champions.map((champion,championIndex)=><article key={champion.champion}><span>{String(championIndex+1).padStart(2,'0')}</span><div className="role-best-champion"><img src={championIcon(champion.champion)} alt=""/><span><strong>{champion.champion}</strong><small>{champion.games} {champion.games===1?'match':'matches'}</small></span></div><div><small>WIN RATE</small><strong>{pct(champion.winRate)}</strong></div><div><small>KDA</small><strong>{num(champion.kda,2)}</strong></div><div><small>CS / MIN</small><strong>{num(champion.csPerMinute,2)}</strong></div><div><small>VISION / MIN</small><strong>{num(champion.visionPerMinute,2)}</strong></div></article>)}</div></div>}</article>})}</div>
      {!rankings.length&&<div className="role-empty">No tracked performances have been recorded for this role.</div>}
    </section>
  </>;
}

function ChampionCompletion({data,player,onOpenMatch}:{data:TrackerData;player:string;onOpenMatch:(id:number)=>void}) {
  const [target,setTarget]=useState<1|3>(1);
  const [selectedChampion,setSelectedChampion]=useState<string|null>(null);
  useEffect(()=>{setTarget(1);setSelectedChampion(null)},[player]);
  const playerRows=data.performances.filter(row=>row.tracked&&row.player===player);
  const winsByChampion=new Map<string,Performance[]>();
  playerRows.forEach(row=>{if(data.matches.find(match=>match.id===row.matchId)?.result==="Win")winsByChampion.set(row.champion,[...(winsByChampion.get(row.champion)??[]),row])});
  winsByChampion.forEach(rows=>rows.sort((a,b)=>b.matchId-a.matchId));
  const completed=data.champions.filter(champion=>(winsByChampion.get(champion)?.length??0)>=target);
  const total=data.champions.length;
  const progress=total?completed.length/total:0;
  const selectedWins=selectedChampion?(winsByChampion.get(selectedChampion)??[]).slice(0,target):[];
  return <><section className="panel champion-completion"><div className="panel-head"><div><p>CHAMPION COMPLETION</p><h3>Victories across the roster</h3></div><div className="completion-toggle" role="group" aria-label="Victory target"><button type="button" className={target===1?'active':''} onClick={()=>{setTarget(1);setSelectedChampion(null)}}>1+ Win</button><button type="button" className={target===3?'active':''} onClick={()=>{setTarget(3);setSelectedChampion(null)}}>3+ Wins</button></div></div><div className="completion-body"><div className="completion-ring" role="img" aria-label={`${completed.length} of ${total} champions completed`} style={{background:`conic-gradient(var(--gold2) 0 ${progress*100}%,#17303e ${progress*100}% 100%)`}}><span><b>{pct(progress)}</b><small>COMPLETE</small></span></div><div className="completion-copy"><span>{target===1?'ONE-WIN CHALLENGE':'THREE-WIN CHALLENGE'}</span><strong>{completed.length}<small> / {total} champions</small></strong><p>{playerName(player)} has earned at least {target} {target===1?'win':'wins'} on {completed.length} champion{completed.length===1?'':'s'}.</p><div className="completion-progress" aria-hidden="true"><i style={{width:pct(progress)}}/></div><small>{Math.max(0,total-completed.length)} champion{total-completed.length===1?'':'s'} remaining</small></div></div><div className="completion-roster"><div className="completion-roster-head"><b>CHAMPION ROSTER</b><span>Color shows progress toward {target} {target===1?'win':'wins'}</span></div><div className="completion-icon-grid">{data.champions.map(champion=>{const wins=winsByChampion.get(champion)?.length??0;const fill=Math.min(1,wins/target);const selected=selectedChampion===champion;return <button type="button" disabled={!wins} aria-label={`${champion}: ${wins} ${wins===1?'win':'wins'}${wins?'. Show win details.':''}`} aria-expanded={selected} className={`${fill>=1?'complete':wins?'partial':'empty'} ${selected?'selected':''}`} onClick={()=>setSelectedChampion(selected?null:champion)} key={champion}><span className="completion-icon"><img className="gray" src={championIcon(champion)} alt=""/><i style={{width:`${fill*100}%`}}><img src={championIcon(champion)} alt=""/></i></span><small>{champion}</small>{wins>0&&<b>{wins}</b>}</button>})}</div></div></section>{selectedChampion&&selectedWins.length>0&&<section className="panel completion-win-panel"><div className="panel-head"><div><p>CHAMPION VICTORIES</p><h3>{playerName(player)} · {selectedChampion}</h3></div><button type="button" onClick={()=>setSelectedChampion(null)}>Close ×</button></div><div className="completion-win-list champion-history-list">{selectedWins.map(row=>{const match=data.matches.find(item=>item.id===row.matchId)!;return <button type="button" key={row.id} onClick={()=>onOpenMatch(match.id)}><span className="result win">W</span><div><b>Match #{match.id}</b><small>{new Date(match.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div><div><small>ROLE</small><b><RoleLabel role={row.role}/></b></div><div><small>K / D / A</small><b>{row.kills} / {row.deaths} / {row.assists}</b></div><div><small>CS · VISION</small><b>{row.cs} · {row.vision}</b></div><i>›</i></button>})}</div></section>}</>;
}

function PartyPerformance({data,player,onOpenMatch}:{data:TrackerData;player:string;onOpenMatch:(id:number)=>void}) {
  const [selection,setSelection]=useState<{kind:"queue"|"teammate";value:number|string}|null>(null);
  useEffect(()=>setSelection(null),[player]);
  const playerRows=data.performances.filter(p=>p.tracked&&p.player===player);
  const playerMatchIds=new Set(playerRows.map(p=>p.matchId));
  const playerMatches=data.matches.filter(match=>playerMatchIds.has(match.id));
  const queueStats=[1,2,3,4,5].map(size=>{const matches=playerMatches.filter(match=>match.groupSize===size);return {size,matches,wins:matches.filter(match=>match.result==="Win").length}});
  const teammateStats=data.players.filter(name=>name!==player).map(name=>{const matchIds=new Set(data.performances.filter(p=>p.tracked&&p.player===name).map(p=>p.matchId));const matches=playerMatches.filter(match=>matchIds.has(match.id));return {name,matches,wins:matches.filter(match=>match.result==="Win").length}}).filter(row=>row.matches.length>0).sort((a,b)=>b.wins/b.matches.length-a.wins/a.matches.length||b.matches.length-a.matches.length||playerName(a.name).localeCompare(playerName(b.name)));
  const selectedMatches=selection?(selection.kind==="queue"?playerMatches.filter(match=>match.groupSize===selection.value):playerMatches.filter(match=>data.performances.some(p=>p.tracked&&p.player===selection.value&&p.matchId===match.id))).sort((a,b)=>b.id-a.id):[];
  const selectionLabel=selection?.kind==="queue"?(selection.value===1?"Solo":selection.value===2?"Duo":`${selection.value}-player party`):selection?`With ${playerName(String(selection.value))}`:"";
  const toggle=(next:{kind:"queue"|"teammate";value:number|string})=>setSelection(current=>current?.kind===next.kind&&current.value===next.value?null:next);
  return <><section className="panel party-performance"><div className="panel-head"><div><p>PARTY PERFORMANCE</p><h3>Queue size and teammate results</h3></div><span>Select a row to view its matches</span></div><div className="party-performance-grid"><div className="queue-size-performance"><div className="party-section-head"><b>PERFORMANCE BY QUEUE SIZE</b><span>Solo through full party</span></div>{queueStats.map(row=>{const selected=selection?.kind==="queue"&&selection.value===row.size;return <button type="button" className={`party-stat-row ${selected?'selected':''}`} disabled={!row.matches.length} aria-expanded={selected} onClick={()=>toggle({kind:"queue",value:row.size})} key={row.size}><div><b>{row.size===1?'Solo':row.size===2?'Duo':`${row.size} Players`}</b><small>{row.matches.length} {row.matches.length===1?'match':'matches'} · {row.wins}W–{row.matches.length-row.wins}L</small></div><div className="party-result-bar" aria-label={`${row.wins} wins and ${row.matches.length-row.wins} losses`}><i className="wins" style={{width:row.matches.length?pct(row.wins/row.matches.length):'0%'}}/><i className="losses" style={{width:row.matches.length?pct((row.matches.length-row.wins)/row.matches.length):'0%'}}/></div><strong>{row.matches.length?pct(row.wins/row.matches.length):'—'}</strong></button>})}</div><div className="teammate-performance"><div className="party-section-head"><b>PERFORMANCE WITH TEAMMATES</b><span>Ranked by win rate</span></div>{teammateStats.length?<div className="teammate-table"><div className="teammate-table-head"><span>#</span><span>TEAMMATE</span><span>TOGETHER</span><span>RECORD</span><span>WIN RATE</span></div>{teammateStats.map((row,index)=>{const selected=selection?.kind==="teammate"&&selection.value===row.name;return <button type="button" className={`teammate-row ${selected?'selected':''}`} aria-expanded={selected} onClick={()=>toggle({kind:"teammate",value:row.name})} key={row.name}><span>{String(index+1).padStart(2,'0')}</span><b>{playerName(row.name)}{row.matches.length<3&&<small>SMALL SAMPLE</small>}</b><span>{row.matches.length}</span><span>{row.wins}W–{row.matches.length-row.wins}L</span><strong>{pct(row.wins/row.matches.length)}</strong></button>})}</div>:<div className="party-empty">No matches with other archived players yet.</div>}</div></div></section>{selection&&<section className="panel party-match-panel"><div className="panel-head"><div><p>PARTY MATCH HISTORY</p><h3>{playerName(player)} · {selectionLabel}</h3></div><button type="button" onClick={()=>setSelection(null)}>Close ×</button></div><div className="party-match-list champion-history-list">{selectedMatches.map(match=>{const row=playerRows.find(p=>p.matchId===match.id)!;return <button type="button" key={match.id} onClick={()=>onOpenMatch(match.id)}><span className={`result ${match.result.toLowerCase()}`}>{match.result[0]}</span><div><b>Match #{match.id}</b><small>{new Date(match.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div><div><small>CHAMPION</small><b className="role-match-champion"><img src={championIcon(row.champion)} alt=""/>{row.champion}</b></div><div><small>ROLE</small><b><RoleLabel role={row.role}/></b></div><div><small>K / D / A</small><b>{row.kills} / {row.deaths} / {row.assists}</b></div><i>›</i></button>})}</div></section>}</>;
}

function InsightsArchive({data,lifetimeData,onOpenMatch}:{data:TrackerData;lifetimeData:TrackerData;onOpenMatch:(id:number)=>void}) {
  type InsightsTab="trends"|"players"|"records";
  type LifetimeSort="player"|"matches"|"wins"|"winRate"|"kills"|"deaths"|"assists"|"kda"|"cs"|"vision";
  const [insightsTab,setInsightsTab]=useState<InsightsTab>("trends");
  const [lifetimeSort,setLifetimeSort]=useState<LifetimeSort>("matches");
  const [lifetimeSortDirection,setLifetimeSortDirection]=useState<"desc"|"asc">("desc");
  const matches=[...data.matches].sort((a,b)=>a.id-b.id);
  const tracked=data.performances.filter(p=>p.tracked);
  const recent=matches.slice(-10);
  const previous=matches.slice(-20,-10);
  const recentIds=new Set(recent.map(m=>m.id));
  const recentRows=tracked.filter(p=>recentIds.has(p.matchId));
  const recentTotals=recentRows.reduce((a,p)=>({kills:a.kills+p.kills,deaths:a.deaths+p.deaths,assists:a.assists+p.assists}),{kills:0,deaths:0,assists:0});
  const recentWins=recent.filter(m=>m.result==="Win").length;
  const previousWins=previous.filter(m=>m.result==="Win").length;
  const pairMap=new Map<string,{players:string[];games:number;wins:number}>();
  matches.forEach(match=>{const players=[...new Set(tracked.filter(p=>p.matchId===match.id).map(p=>p.player))].sort();for(let i=0;i<players.length;i++)for(let j=i+1;j<players.length;j++){const key=`${players[i]}|${players[j]}`;const pair=pairMap.get(key)??{players:[players[i],players[j]],games:0,wins:0};pair.games++;pair.wins+=match.result==="Win"?1:0;pairMap.set(key,pair)}});
  const pairs=[...pairMap.values()].filter(pair=>pair.games>=2).sort((a,b)=>b.wins/b.games-a.wins/a.games||b.games-a.games).slice(0,6);
  const comboMap=new Map<string,Performance[]>();
  tracked.forEach(p=>{const key=`${p.player}|${p.champion}`;comboMap.set(key,[...(comboMap.get(key)??[]),p])});
  const combos=[...comboMap.entries()].map(([key,rows])=>{const [player,champion]=key.split('|');const wins=rows.filter(p=>data.matches.find(m=>m.id===p.matchId)?.result==="Win").length;return {player,champion,games:rows.length,winRate:wins/rows.length}}).sort((a,b)=>b.games-a.games).slice(0,14);
  const maxComboGames=Math.max(1,...combos.map(c=>c.games));
  const flexibility=data.players.map(player=>{const rows=tracked.filter(p=>p.player===player);const counts=data.roles.map(role=>({role,games:rows.filter(p=>p.role===role).length})).filter(x=>x.games);return {player,total:rows.length,counts}}).filter(x=>x.total).sort((a,b)=>b.counts.length-a.counts.length||b.total-a.total);
  const sideStats=["Blue","Purple"].map(side=>{const rows=matches.filter(m=>m.side===side);return {label:`${side} side`,games:rows.length,wins:rows.filter(m=>m.result==="Win").length}});
  const groupStats=[...new Set(matches.map(m=>m.groupSize))].sort((a,b)=>a-b).map(size=>{const rows=matches.filter(m=>m.groupSize===size);return {label:`${size} player${size===1?'':'s'}`,games:rows.length,wins:rows.filter(m=>m.result==="Win").length}});
  const durationStats=[{label:"Under 25 min",test:(m:Match)=>m.duration<25},{label:"25–35 min",test:(m:Match)=>m.duration>=25&&m.duration<=35},{label:"Over 35 min",test:(m:Match)=>m.duration>35}].map(band=>{const rows=matches.filter(band.test);return {label:band.label,games:rows.length,wins:rows.filter(m=>m.result==="Win").length}});
  const longest={Win:0,Loss:0};let runType="",runLength=0;matches.forEach(match=>{if(match.result===runType)runLength++;else{runType=match.result;runLength=1}longest[match.result as "Win"|"Loss"]=Math.max(longest[match.result as "Win"|"Loss"],runLength)});
  const latestResult=matches.at(-1)?.result??"—";let currentStreak=0;for(let i=matches.length-1;i>=0&&matches[i].result===latestResult;i--)currentStreak++;
  const ratedRows=tracked.map(p=>{const match=data.matches.find(m=>m.id===p.matchId);return {...p,csPerMinute:p.cs/Math.max(1,match?.duration??0),visionPerMinute:p.vision/Math.max(1,match?.duration??0),matchKda:kda(p)}});
  const highest=(selector:(p:(typeof ratedRows)[number])=>number)=>[...ratedRows].sort((a,b)=>selector(b)-selector(a))[0];
  const recordRows=[{label:"Most kills",row:highest(p=>p.kills),value:(p:(typeof ratedRows)[number])=>String(p.kills)},{label:"Most assists",row:highest(p=>p.assists),value:(p:(typeof ratedRows)[number])=>String(p.assists)},{label:"Highest KDA",row:highest(p=>p.matchKda),value:(p:(typeof ratedRows)[number])=>num(p.matchKda,2)},{label:"Highest CS / min",row:highest(p=>p.csPerMinute),value:(p:(typeof ratedRows)[number])=>num(p.csPerMinute,2)},{label:"Highest vision / min",row:highest(p=>p.visionPerMinute),value:(p:(typeof ratedRows)[number])=>num(p.visionPerMinute,2)}].filter(record=>record.row);
  const insightBars=(rows:{label:string;games:number;wins:number}[])=><div className="insight-bars">{rows.map(row=><div key={row.label}><span>{row.label}<small>{row.games} matches</small></span><div><i style={{width:row.games?pct(row.wins/row.games):'0%'}}/></div><strong>{row.games?pct(row.wins/row.games):'—'}</strong></div>)}</div>;

  const lifetimeRows=lifetimeData.players.map(player=>{const rows=lifetimeData.performances.filter(row=>row.tracked&&row.player===player);const matchIds=new Set(rows.map(row=>row.matchId));const playerMatches=lifetimeData.matches.filter(match=>matchIds.has(match.id));const totals=rows.reduce((sum,row)=>({kills:sum.kills+row.kills,deaths:sum.deaths+row.deaths,assists:sum.assists+row.assists,cs:sum.cs+row.cs,vision:sum.vision+row.vision}),{kills:0,deaths:0,assists:0,cs:0,vision:0});const wins=playerMatches.filter(match=>match.result==="Win").length;return {player,matches:playerMatches.length,wins,winRate:wins/Math.max(1,playerMatches.length),...totals,kda:(totals.kills+totals.assists)/Math.max(1,totals.deaths)}}).filter(row=>row.matches>0).sort((a,b)=>{const comparison=lifetimeSort==="player"?playerName(a.player).localeCompare(playerName(b.player)):a[lifetimeSort]-b[lifetimeSort];return (lifetimeSortDirection==="desc"?-comparison:comparison)||b.matches-a.matches||playerName(a.player).localeCompare(playerName(b.player))});
  const sortLifetime=(column:LifetimeSort)=>{if(lifetimeSort===column)setLifetimeSortDirection(direction=>direction==="desc"?"asc":"desc");else{setLifetimeSort(column);setLifetimeSortDirection("desc")}};
  const LifetimeHeading=({column,label}:{column:LifetimeSort;label:string})=><button type="button" className={lifetimeSort===column?'active':''} onClick={()=>sortLifetime(column)}><span>{label}</span><i aria-hidden="true">{lifetimeSort===column?(lifetimeSortDirection==="desc"?'▼':'▲'):'↕'}</i></button>;

  return <div className="insights-archive" data-tab={insightsTab}>
    <div className="insights-tabs" style={{order:-2}} role="tablist" aria-label="Insight categories">{([['trends','Archive Trends'],['players','Player Insights'],['records','Records']] as [InsightsTab,string][]).map(([id,label])=><button type="button" role="tab" aria-selected={insightsTab===id} className={insightsTab===id?'active':''} onClick={()=>setInsightsTab(id)} key={id}>{label}</button>)}</div>
    <section className="insight-hero"><div><p>ARCHIVE INTELLIGENCE</p><h2>Patterns from the Rift</h2><span>Trends, partnerships, flexibility, and standout performances across the full archive.</span></div><div className="insight-hero-stats"><div><small>LAST 10 WIN RATE</small><b>{recent.length?pct(recentWins/recent.length):'—'}</b></div><div><small>LAST 10 KDA</small><b>{num((recentTotals.kills+recentTotals.assists)/Math.max(1,recentTotals.deaths),2)}</b></div><div><small>CURRENT STREAK</small><b>{currentStreak} {latestResult}</b></div></div></section>
    <section className="insight-grid insight-top-grid">
      <article className="panel insight-recent"><div className="panel-head"><div><p>RECENT FORM</p><h3>Last {recent.length} matches</h3></div><span>Compared with the previous {previous.length}</span></div><div className="form-bars"><div className="form-bar-row recent-period"><div className="form-bar-label"><span>Recent {recent.length}</span><small>{recentWins}W · {recent.length-recentWins}L</small></div><div className="form-bar" aria-label={`${recentWins} wins and ${recent.length-recentWins} losses`}><i className="wins" style={{width:recent.length?pct(recentWins/recent.length):'0%'}}/><i className="losses" style={{width:recent.length?pct((recent.length-recentWins)/recent.length):'0%'}}/></div><b>{recent.length?pct(recentWins/recent.length):'—'}</b></div><div className="recent-match-links" aria-label="Last ten matches">{[...recent].reverse().map(match=><button type="button" className={match.result.toLowerCase()} title={`Open Match #${match.id}`} onClick={()=>onOpenMatch(match.id)} key={match.id}><span>{match.result[0]}</span><small>#{match.id}</small></button>)}</div><div className="form-bar-row previous-period"><div className="form-bar-label"><span>Previous {previous.length}</span><small>{previousWins}W · {previous.length-previousWins}L</small></div><div className="form-bar" aria-label={`${previousWins} wins and ${previous.length-previousWins} losses`}><i className="wins" style={{width:previous.length?pct(previousWins/previous.length):'0%'}}/><i className="losses" style={{width:previous.length?pct((previous.length-previousWins)/previous.length):'0%'}}/></div><b>{previous.length?pct(previousWins/previous.length):'—'}</b></div></div></article>
      <article className="panel insight-synergy"><div className="panel-head"><div><p>PLAYER SYNERGY</p><h3>Strongest duos</h3></div><span>Minimum 2 matches</span></div><div className="synergy-list">{pairs.map((pair,index)=><div key={pair.players.join('|')}><span>{String(index+1).padStart(2,'0')}</span><b>{pair.players.map(playerName).join(' + ')}</b><small>{pair.games} together{pair.games<4?' · small sample':''}</small><strong>{pct(pair.wins/pair.games)}</strong></div>)}</div></article>
    </section>
    <section className="panel comfort-panel"><div className="panel-head"><div><p>COMFORT VS. SUCCESS</p><h3>Champion volume and win rate</h3></div><span>Bubble size reflects matches played</span></div><div className="comfort-chart"><div className="comfort-y"><span>100%</span><span>50%</span><span>0%</span></div><div className="comfort-plot">{combos.map(combo=><div className="comfort-dot" title={`${playerName(combo.player)} · ${combo.champion}: ${combo.games} matches, ${pct(combo.winRate)} win rate`} style={{left:`${Math.max(5,combo.games/maxComboGames*92)}%`,bottom:`${Math.max(3,combo.winRate*90)}%`,width:`${18+combo.games/maxComboGames*22}px`,height:`${18+combo.games/maxComboGames*22}px`}} key={`${combo.player}-${combo.champion}`}><img src={championIcon(combo.champion)} alt=""/><span>{playerName(combo.player)}</span></div>)}</div><div className="comfort-x">Fewer matches <span>Match volume →</span> More matches</div></div><div className="comfort-legend">{combos.slice(0,6).map(combo=><span key={`${combo.player}-${combo.champion}`}><img src={championIcon(combo.champion)} alt=""/>{playerName(combo.player)} · {combo.champion}<b>{combo.games} / {pct(combo.winRate)}</b></span>)}</div></section>
    <section className="panel flexibility-panel"><div className="panel-head"><div><p>ROLE FLEXIBILITY</p><h3>Player role distribution</h3></div><span>Matches across every played role</span></div><div className="flexibility-list">{flexibility.map(row=><div key={row.player}><b>{playerName(row.player)}</b><span>{row.counts.length} roles · {row.total} matches</span><div>{row.counts.map(role=><i title={`${role.role}: ${role.games} matches`} style={{width:pct(role.games/row.total),background:roleColors[role.role]}} key={role.role}/>)}</div><small>{row.counts.map(role=><span key={role.role}><img src={roleIcon(role.role)} alt=""/>{role.role} {role.games}</span>)}</small></div>)}</div></section>
    <section className="insight-grid insight-performance-grid">
      <article className="panel"><div className="panel-head"><div><p>SIDE PERFORMANCE</p><h3>Blue vs. Purple</h3></div></div>{insightBars(sideStats)}</article>
      <article className="panel"><div className="panel-head"><div><p>GROUP SIZE</p><h3>Party performance</h3></div></div>{insightBars(groupStats)}</article>
      <article className="panel"><div className="panel-head"><div><p>MATCH LENGTH</p><h3>Duration trends</h3></div></div>{insightBars(durationStats)}</article>
    </section>
    <section className="insight-grid insight-bottom-grid">
      <article className="panel streak-panel"><div className="panel-head"><div><p>STREAKS</p><h3>Momentum records</h3></div></div><div className="streak-grid"><div><small>CURRENT</small><b>{currentStreak}</b><span>{latestResult} streak</span></div><div><small>LONGEST WIN</small><b>{longest.Win}</b><span>matches</span></div><div><small>LONGEST LOSS</small><b>{longest.Loss}</b><span>matches</span></div></div></article>
      <article className="panel records-panel"><div className="panel-head"><div><p>PERSONAL RECORDS</p><h3>Single-match standouts</h3></div><span>Tracked performances</span></div><div className="records-grid">{recordRows.map(record=>{const row=record.row!;return <div key={record.label}><small>{record.label}</small><b>{record.value(row)}</b><span><img src={championIcon(row.champion)} alt=""/>{playerName(row.player)} · {row.champion}</span><em>Match #{row.matchId}</em></div>})}</div></article>
    </section>
    <section className="panel lifetime-records"><div className="panel-head"><div><p>CAREER COMPARISON</p><h3>Lifetime records</h3></div><span>All recorded games · solo and group</span></div><div className="lifetime-table"><div className="lifetime-head"><span>#</span><LifetimeHeading column="player" label="PLAYER"/><LifetimeHeading column="matches" label="MATCHES"/><LifetimeHeading column="wins" label="WINS"/><LifetimeHeading column="winRate" label="WIN RATE"/><LifetimeHeading column="kills" label="KILLS"/><LifetimeHeading column="deaths" label="DEATHS"/><LifetimeHeading column="assists" label="ASSISTS"/><LifetimeHeading column="kda" label="KDA"/><LifetimeHeading column="cs" label="CS"/><LifetimeHeading column="vision" label="VISION"/></div>{lifetimeRows.map((row,index)=><div className="lifetime-row" key={row.player}><span>{String(index+1).padStart(2,'0')}</span><b>{playerName(row.player)}</b><strong>{row.matches}</strong><strong>{row.wins}</strong><strong>{pct(row.winRate)}</strong><strong>{row.kills}</strong><strong>{row.deaths}</strong><strong>{row.assists}</strong><strong>{num(row.kda,2)}</strong><strong>{row.cs}</strong><strong>{row.vision}</strong></div>)}</div></section>
  </div>;
}

function AuditArchive({events,onOpenMatch,availableMatchIds}:{events:AuditEvent[];onOpenMatch:(id:number)=>void;availableMatchIds:Set<number>}) {
  const displayValue=(value:unknown)=>{if(value===null||value===undefined||value==="")return "None";if(typeof value==="number")return String(value);return String(value).length>80?`${String(value).slice(0,77)}…`:String(value)};
  return <section className="panel audit-panel"><div className="panel-head"><div><p>RECORD GOVERNANCE</p><h3>Match audit history</h3></div><span>{events.length} recorded change{events.length===1?'':'s'}</span></div><div className="audit-notice"><i>⌁</i><div><b>Administrator view</b><span>This permanent history is generated automatically whenever a match is published, edited, deleted, or restored.</span></div></div>{events.length?<div className="audit-list">{events.map(event=>{const changes=Object.entries(event.changes??{});const exists=availableMatchIds.has(event.matchId);return <article key={event.id}><div className={`audit-action ${event.action}`}><i>{event.action==="created"?'＋':event.action==="deleted"?'×':event.action==="restored"?'↻':'✎'}</i><span>{event.action==="created"?'PUBLISHED':event.action==="deleted"?'DELETED':event.action==="restored"?'RESTORED':'EDITED'}</span></div><div className="audit-body"><button type="button" disabled={!exists} onClick={()=>onOpenMatch(event.matchId)}>Match #{event.matchId}</button><p>{event.action==="created"?'A new match record was published.':event.action==="deleted"?'The match was hidden from the archive and retained for recovery.':event.action==="restored"?'The match and all player performances were restored to the archive.':changes.length?`${changes.length} match field${changes.length===1?' was':'s were'} changed.`:'The match record or player performances were updated.'}</p>{changes.length>0&&<div className="audit-changes">{changes.map(([field,change])=><span key={field}><b>{field}</b><em>{displayValue(change.from)}</em><i>→</i><strong>{displayValue(change.to)}</strong></span>)}</div>}</div><div className="audit-meta"><b>{event.actorEmail}</b><time dateTime={event.createdAt}>{new Date(event.createdAt).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})}</time></div></article>})}</div>:<div className="audit-empty"><b>No audited changes yet</b><span>New publications, edits, deletions, and restorations will appear here automatically.</span></div>}</section>;
}

function UserAccessPanel({profiles,currentUserId,canManageRoles,onRoleChange}:{profiles:UserProfile[];currentUserId:string;canManageRoles:boolean;onRoleChange?:(userId:string,role:UserRole)=>Promise<void>}) {
  const [updating,setUpdating]=useState<string|null>(null);
  return <section className="panel access-panel"><div className="panel-head"><div><p>ACCESS CONTROL</p><h3>Archive roles</h3></div><span>{profiles.length} registered account{profiles.length===1?'':'s'} · {canManageRoles?'Role management':'Read only'}</span></div><div className="access-list">{profiles.map(profile=><article key={profile.userId}><div><b>{profile.email}</b><span>{profile.userId===currentUserId?'Current account':'Archive contributor'}</span></div><label>ROLE{canManageRoles?<select disabled={updating===profile.userId} value={profile.role} onChange={async e=>{const role=e.target.value as UserRole;setUpdating(profile.userId);await onRoleChange?.(profile.userId,role);setUpdating(null)}}><option value="user">User</option><option value="moderator">Moderator</option><option value="administrator">Administrator</option></select>:<strong className="role-readonly">{profile.role}</strong>}</label></article>)}</div><div className="access-policy"><b>USER</b><span>Can publish matches and edit or delete only matches they personally uploaded.</span><b>MODERATOR</b><span>Can review accounts and audit history, and edit, delete, or restore any match.</span><b>ADMINISTRATOR</b><span>Has Moderator permissions and can also manage account roles.</span></div></section>;
}

function PendingReviewQueue({submissions,onReview,onReject}:{submissions:PendingSubmission[];onReview:(submission:PendingSubmission)=>void;onReject:(id:number)=>Promise<void>}) {
  const [rejecting,setRejecting]=useState<number|null>(null);
  return <section className="panel review-queue"><div className="panel-head"><div><p>CAPTURE MODERATION</p><h3>Matches awaiting review</h3></div><span>{submissions.length} pending submission{submissions.length===1?'':'s'}</span></div><div className="review-notice"><i>!</i><div><b>Not yet part of the archive</b><span>These captures do not affect matches, player profiles, roles, insights, or ratings until a reviewer publishes them.</span></div></div>{submissions.length?<div className="review-list">{submissions.map(submission=><article key={submission.id}><span className={`result ${submission.matchData.result.toLowerCase()}`}>{submission.matchData.result[0]}</span><div className="review-match"><b>{submission.performanceData.map(p=>playerName(p.player)).join(' · ')||'Captured match'}</b><small>{new Date(submission.createdAt).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})} · submitted by {submission.submitterEmail}</small></div><div><small>RECORD</small><b>{submission.matchData.result} · {submission.matchData.ally_side}</b><span>{durationInput(Number(submission.matchData.duration_minutes))}</span></div><div><small>PLAYERS</small><b>{submission.performanceData.length}</b><span>{submission.performanceData.map(p=>`${p.champion} ${p.kills}/${p.deaths}/${p.assists}`).join(' · ')}</span></div><div className="review-actions"><button type="button" onClick={()=>onReview(submission)}>Review &amp; edit</button><button type="button" className="reject" disabled={rejecting===submission.id} onClick={async()=>{if(!window.confirm('Reject this captured match? It will not be added to the archive.'))return;setRejecting(submission.id);await onReject(submission.id);setRejecting(null)}}>{rejecting===submission.id?'Rejecting…':'Reject'}</button></div></article>)}</div>:<div className="audit-empty"><b>No matches need review</b><span>New recorder captures will appear here automatically.</span></div>}</section>;
}

function DeletedMatchesPanel({matches,onRestore}:{matches:Match[];onRestore:(id:number)=>Promise<void>}) {
  const [restoring,setRestoring]=useState<number|null>(null);
  return <section className="panel deleted-panel"><div className="panel-head"><div><p>RECOVERY</p><h3>Deleted matches</h3></div><span>{matches.length} recoverable match{matches.length===1?'':'es'}</span></div>{matches.length?<div className="deleted-list">{matches.map(match=><article key={match.id}><span className={`result ${match.result.toLowerCase()}`}>{match.result[0]}</span><div><b>Match #{match.id}</b><small>{new Date(match.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} · {match.groupSize} player{match.groupSize===1?'':'s'}</small></div><div><small>SIDE</small><b>{match.side}</b></div><div><small>DURATION</small><b>{durationInput(match.duration)}</b></div><button type="button" disabled={restoring===match.id} onClick={async()=>{setRestoring(match.id);await onRestore(match.id);setRestoring(null)}}>{restoring===match.id?'Restoring…':'Restore match'}</button></article>)}</div>:<div className="audit-empty"><b>No deleted matches</b><span>Matches removed by Users or Administrators will remain recoverable here.</span></div>}</section>;
}

export default function Home() {
  const [data, setData] = useState<TrackerData|null>(null);
  const [user,setUser]=useState<User|null>(null);
  const [auditEvents,setAuditEvents]=useState<AuditEvent[]>([]);
  const [profiles,setProfiles]=useState<UserProfile[]>([]);
  const [deletedMatches,setDeletedMatches]=useState<Match[]>([]);
  const [pendingSubmissions,setPendingSubmissions]=useState<PendingSubmission[]>([]);
  const [reviewingSubmission,setReviewingSubmission]=useState<PendingSubmission|null>(null);
  const [authEmail,setAuthEmail]=useState("");
  const [authMessage,setAuthMessage]=useState("");
  const [tab,setTab] = useState<Tab>("overview");
  const [auditView,setAuditView] = useState<"changelog"|"deleted">("changelog");
  const [player,setPlayer] = useState("Dane");
  const [playerMatchScope,setPlayerMatchScope] = useState<PlayerMatchScope>("group");
  const [expandedChampion,setExpandedChampion] = useState<string|null>(null);
  const [showAllChampions,setShowAllChampions] = useState(false);
  const [showAllPlayerMatches,setShowAllPlayerMatches] = useState(false);
  const [playerMatchPage,setPlayerMatchPage] = useState(0);
  const [selectedRole,setSelectedRole] = useState<string|null>(null);
  const [query,setQuery] = useState("");
  const [resultFilter,setResultFilter] = useState("All");
  const [playerFilters,setPlayerFilters] = useState<string[]>([]);
  const [expanded,setExpanded] = useState<number|null>(null);
  const [editingMatch,setEditingMatch] = useState<number|null>(null);
  const [feedbackSubject,setFeedbackSubject] = useState("");
  const [feedbackContext,setFeedbackContext] = useState("");
  const [feedbackStatus,setFeedbackStatus] = useState("");
  const [feedbackSubmitting,setFeedbackSubmitting] = useState(false);
  const [feedbackView,setFeedbackView] = useState<"submit"|"requests">("submit");
  const [feedbackItems,setFeedbackItems] = useState<FeedbackItem[]>([]);
  const [feedbackLoading,setFeedbackLoading] = useState(false);
  const [showDeclined,setShowDeclined] = useState(false);

  const loadData=async()=>{
    const [m,p,pl,c,r]=await Promise.all([
      supabase.from("matches").select("*").is("deleted_at",null).order("id"),
      supabase.from("performances").select("*").order("id"),
      supabase.from("players").select("name").order("name"),
      supabase.from("champions").select("name").order("name"),
      supabase.from("roles").select("name").order("name"),
    ]);
    const error=m.error||p.error||pl.error||c.error||r.error;
    if(error){const fallback=await fetch("./tracker-data.json").then(x=>x.json());setData(fallback);return;}
    setData({
      matches:(m.data??[]).map(x=>({id:x.id,gameId:x.game_id??"",date:x.match_date,groupSize:x.friend_group_size,side:x.ally_side,result:x.result,duration:Number(x.duration_minutes),notes:x.notes??"",createdBy:x.created_by})),
      performances:(p.data??[]).map(x=>({id:x.id,matchId:x.match_id,team:x.team,tracked:x.tracked,player:x.player,champion:x.champion,role:x.role,kills:x.kills,deaths:x.deaths,assists:x.assists,cs:x.cs,vision:x.vision})),
      players:(pl.data??[]).map(x=>x.name),champions:(c.data??[]).map(x=>x.name),roles:(r.data??[]).map(x=>x.name),
    });
  };
  const loadAudit=async()=>{const {data:rows,error}=await supabase.from("match_audit_log").select("id,match_id,action,actor_email,changed_fields,created_at").order("created_at",{ascending:false});if(!error)setAuditEvents((rows??[]).map(row=>({id:row.id,matchId:row.match_id,action:row.action,actorEmail:row.actor_email,changes:row.changed_fields??{},createdAt:row.created_at})))};
  const loadDeletedMatches=async()=>{const {data:rows,error}=await supabase.from("matches").select("*").not("deleted_at","is",null).order("deleted_at",{ascending:false});if(!error)setDeletedMatches((rows??[]).map(x=>({id:x.id,gameId:x.game_id??"",date:x.match_date,groupSize:x.friend_group_size,side:x.ally_side,result:x.result,duration:Number(x.duration_minutes),notes:x.notes??"",createdBy:x.created_by})))};
  const loadPendingSubmissions=async()=>{const {data:rows,error}=await supabase.from("pending_match_submissions").select("id,submitted_by,submitter_email,match_data,performance_data,capture_metadata,created_at").eq("status","pending").order("created_at",{ascending:false});if(!error)setPendingSubmissions((rows??[]).map(row=>({id:row.id,submittedBy:row.submitted_by,submitterEmail:row.submitter_email,matchData:row.match_data,performanceData:row.performance_data,captureMetadata:row.capture_metadata??{},createdAt:row.created_at})))};
  const loadFeedback=async()=>{setFeedbackLoading(true);const {data:rows,error}=await supabase.from("feedback").select("id,subject,context,status,submitted_by,submitter_email,created_at,updated_at").order("created_at",{ascending:false});setFeedbackLoading(false);if(!error)setFeedbackItems((rows??[]).map(row=>({id:row.id,subject:row.subject,context:row.context,status:row.status as FeedbackStatus,submittedBy:row.submitted_by,submitterEmail:row.submitter_email,createdAt:row.created_at,updatedAt:row.updated_at}))) };
  const loadProfiles=async(userId:string)=>{const {data:rows,error}=await supabase.from("user_profiles").select("user_id,email,role").order("email");if(!error){const mapped=(rows??[]).map(row=>({userId:row.user_id,email:row.email,role:row.role}) as UserProfile);setProfiles(mapped);if(mapped.some(profile=>profile.userId===userId&&['administrator','moderator'].includes(profile.role)))Promise.all([loadAudit(),loadDeletedMatches(),loadPendingSubmissions()]);else{setAuditEvents([]);setDeletedMatches([]);setPendingSubmissions([])}}};
  useEffect(()=>{loadData();supabase.auth.getUser().then(({data})=>{setUser(data.user);if(data.user)loadProfiles(data.user.id)});const {data:listener}=supabase.auth.onAuthStateChange((_e,s)=>{setUser(s?.user??null);if(s?.user)loadProfiles(s.user.id);else{setAuditEvents([]);setDeletedMatches([]);setPendingSubmissions([]);setProfiles([])}});return()=>listener.subscription.unsubscribe();},[]);
  useEffect(()=>{if(user&&tab==="feedback"&&feedbackView==="requests")loadFeedback()},[user,tab,feedbackView]);

  const sendMagicLink=async()=>{setAuthMessage("Sending…");const {error}=await supabase.auth.signInWithOtp({email:authEmail,options:{emailRedirectTo:"https://eupharias.github.io/classic-match-archive/"}});setAuthMessage(error?error.message:"Check your email for the sign-in link.")};
  const groupData=useMemo(()=>data?scopedTrackerData(data,match=>match.groupSize>=2):null,[data]);
  const playerData=useMemo(()=>data?scopedTrackerData(data,match=>playerMatchScope==="all"||(playerMatchScope==="solo"?match.groupSize===1:match.groupSize>=2)):null,[data,playerMatchScope]);
  const stats = useMemo(() => {
    if(!groupData) return null;
    const wins=groupData.matches.filter(m=>m.result==="Win").length;
    const avgDuration=groupData.matches.reduce((a,m)=>a+m.duration,0)/Math.max(1,groupData.matches.length);
    const tracked=groupData.performances.filter(p=>p.tracked);
    const combatTotals=tracked.reduce((totals,p)=>({kills:totals.kills+p.kills,deaths:totals.deaths+p.deaths,assists:totals.assists+p.assists}),{kills:0,deaths:0,assists:0});
    const totalKda=(combatTotals.kills+combatTotals.assists)/Math.max(1,combatTotals.deaths);
    return {wins,winRate:wins/Math.max(1,groupData.matches.length),avgDuration,totalKda,trackedPerformances:tracked.length};
  },[groupData]);

  if(!data || !groupData || !playerData || !stats) return <main className="loading"><div className="crest">C</div><p>Loading the match archive…</p></main>;

  const playerRows=playerData.performances.filter(p=>p.player===player && p.tracked);
  const playerMatchRows=[...playerRows].sort((a,b)=>b.matchId-a.matchId);
  const playerMatchPageCount=Math.ceil(playerMatchRows.length/10);
  const visiblePlayerMatchRows=showAllPlayerMatches?playerMatchRows.slice(playerMatchPage*10,playerMatchPage*10+10):playerMatchRows.slice(0,5);
  const playerMatches=playerRows.map(p=>playerData.matches.find(m=>m.id===p.matchId)).filter(Boolean) as Match[];
  const playerWins=playerMatches.filter(m=>m.result==="Win").length;
  const championMap=Object.values(playerRows.reduce((acc,p)=>{
    const m=playerData.matches.find(x=>x.id===p.matchId); const c=acc[p.champion]??={name:p.champion,games:0,wins:0,kda:0,cs:0};
    c.games++; c.wins+=m?.result==="Win"?1:0; c.kda+=kda(p); c.cs+=p.cs; return acc;
  },{} as Record<string,{name:string;games:number;wins:number;kda:number;cs:number}>)).sort((a,b)=>b.games-a.games);
  const playerRatingsByRole=Object.fromEntries(playerData.roles.map(role=>[role,calculateRoleRatings(playerData,role).get(player)])) as Record<string,number|undefined>;
  const playerRoleStats=playerData.roles.map(role=>{
    const rows=playerRows.filter(p=>p.role===role);
    const wins=rows.filter(p=>playerData.matches.find(m=>m.id===p.matchId)?.result==='Win').length;
    const championCounts=rows.reduce((acc,p)=>(acc[p.champion]=(acc[p.champion]||0)+1,acc),{} as Record<string,number>);
    const favorite=Object.entries(championCounts).sort((a,b)=>b[1]-a[1])[0];
    const totals=rows.reduce((acc,p)=>({kills:acc.kills+p.kills,deaths:acc.deaths+p.deaths,assists:acc.assists+p.assists,cs:acc.cs+p.cs,vision:acc.vision+p.vision,minutes:acc.minutes+(playerData.matches.find(m=>m.id===p.matchId)?.duration??0)}),{kills:0,deaths:0,assists:0,cs:0,vision:0,minutes:0});
    return {role,games:rows.length,wins,favorite:favorite?.[0]??'—',favoriteGames:favorite?.[1]??0,csPerMinute:totals.cs/Math.max(1,totals.minutes),visionPerMinute:totals.vision/Math.max(1,totals.minutes),totalKda:(totals.kills+totals.assists)/Math.max(1,totals.deaths),rating:playerRatingsByRole[role]};
  }).sort((a,b)=>b.games-a.games||a.role.localeCompare(b.role));
  const selectedRoleRows=selectedRole?[...playerRows.filter(p=>p.role===selectedRole)].sort((a,b)=>b.matchId-a.matchId):[];
  const playerTotals=playerRows.reduce((acc,p)=>({kills:acc.kills+p.kills,deaths:acc.deaths+p.deaths,assists:acc.assists+p.assists}),{kills:0,deaths:0,assists:0});
  const mainRole=playerRows.length?Object.entries(playerRows.reduce((a,p)=>(a[p.role]=(a[p.role]||0)+1,a),{} as Record<string,number>)).sort((a,b)=>b[1]-a[1])[0][0]:null;
  let pieCursor=0;const rolePie=playerRoleStats.filter(r=>r.games>0).map(r=>{const start=pieCursor/Math.max(1,playerRows.length)*100;pieCursor+=r.games;const end=pieCursor/Math.max(1,playerRows.length)*100;return `${roleColors[r.role]??'#8ca0ad'} ${start}% ${end}%`}).join(',');
  const filteredMatches=data.matches.filter(m=>(resultFilter==="All"||m.result===resultFilter) && (`${m.id} ${m.notes} ${m.date}`).toLowerCase().includes(query.toLowerCase()) && playerFilters.every(name=>data.performances.some(p=>p.matchId===m.id&&p.player===name))).sort((a,b)=>b.id-a.id);
  const openAndFocusMatch=(id:number)=>{setQuery("");setResultFilter("All");setPlayerFilters([]);setExpanded(id);setTab("matches");requestAnimationFrame(()=>requestAnimationFrame(()=>{const summary=[...document.querySelectorAll<HTMLButtonElement>(".match-summary")].find(button=>button.textContent?.includes(`Match #${id}`));summary?.closest("article")?.scrollIntoView({behavior:"smooth",block:"center"});summary?.focus({preventScroll:true})}))};
  const currentProfile=profiles.find(profile=>profile.userId===user?.id);
  const canManageRoles=currentProfile?.role==="administrator";
  const canModerate=canManageRoles||currentProfile?.role==="moderator";
  const isAdmin=canModerate;
  const feedbackLaneStatuses:FeedbackStatus[]=[...(showDeclined?["Declined" as FeedbackStatus]:[]),"Backlog","Accepted","In Progress","Review Pending","Complete"];
  const pendingInitialMatch=reviewingSubmission?{id:0,gameId:reviewingSubmission.matchData.game_id??"",date:reviewingSubmission.matchData.match_date,groupSize:Number(reviewingSubmission.matchData.friend_group_size),side:reviewingSubmission.matchData.ally_side,result:reviewingSubmission.matchData.result,duration:Number(reviewingSubmission.matchData.duration_minutes),notes:reviewingSubmission.matchData.notes??""}:undefined;
  const pendingInitialPerformances=reviewingSubmission?reviewingSubmission.performanceData.map((p,index)=>({id:index+1,matchId:0,team:'Ally',tracked:true,...p} as Performance)):undefined;
  const deleteMatch=async(match:Match)=>{if(!window.confirm(`Delete Match #${match.id}? It will disappear from the archive but Moderators and Administrators can restore it later.`))return;const {error}=await supabase.rpc("soft_delete_match",{target_match_id:match.id});if(error){window.alert(error.message);return}setExpanded(null);await Promise.all([loadData(),canModerate?loadAudit():Promise.resolve(),canModerate?loadDeletedMatches():Promise.resolve()])};
  const restoreMatch=async(matchId:number)=>{const {error}=await supabase.rpc("restore_match",{target_match_id:matchId});if(error){window.alert(error.message);return}await Promise.all([loadData(),loadAudit(),loadDeletedMatches()])};
  const clearFeedback=()=>{setFeedbackSubject("");setFeedbackContext("");setFeedbackStatus("")};
  const submitFeedback=async()=>{if(!user||!feedbackSubject.trim()||!feedbackContext.trim())return;setFeedbackSubmitting(true);setFeedbackStatus("");const {error}=await supabase.from("feedback").insert({subject:feedbackSubject.trim(),context:feedbackContext.trim(),status:"Backlog"});setFeedbackSubmitting(false);if(error){setFeedbackStatus(error.message);return}setFeedbackSubject("");setFeedbackContext("");setFeedbackStatus("Feedback submitted to the backlog.")};
  const deleteFeedbackItem=async(id:number)=>{const item=feedbackItems.find(entry=>entry.id===id);if(!item||!window.confirm(`Permanently delete “${item.subject}”? This cannot be undone.`))return false;const {error}=await supabase.from("feedback").delete().eq("id",id);if(error){window.alert(error.message);return false}setFeedbackItems(items=>items.filter(entry=>entry.id!==id));return true};
  const updateFeedbackStatus=async(id:number,status:FeedbackStatus)=>{if(status==="DELETED"){await deleteFeedbackItem(id);return}const previous=feedbackItems;setFeedbackItems(items=>items.map(item=>item.id===id?{...item,status}:item));const {error}=await supabase.from("feedback").update({status,updated_at:new Date().toISOString()}).eq("id",id);if(error){setFeedbackItems(previous);window.alert(error.message)}};

  const exportData=()=>{
    const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});
    const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download="classic-match-tracker.json"; a.click(); URL.revokeObjectURL(a.href);
  };

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><img src="./rabadons-cat-favicon.png" alt="Deathcap cat"/></div><div><b>CLASSIC</b><span>Match Archive</span></div></div>
      <nav aria-label="Primary navigation">
        {([['add','Log a Match','＋'],['overview','Overview','⌂'],['players','Players','♙'],['roles','Roles','◇'],['insights','Insights','✦'],['matches','Matches','◫'],['feedback','Roadmap','⚑'],...(canModerate?[['review',`Review${pendingSubmissions.length?` (${pendingSubmissions.length})`:''}`,'!'],['audit','Audit','⌁'],['accounts','Accounts','⚙']]:[])] as [Tab,string,string][]).map(([id,label,icon])=><button key={id} className={tab===id?'active':''} onClick={()=>{if(id==='add')setEditingMatch(null);if(id==='review')setReviewingSubmission(null);setTab(id)}}><i>{icon}</i>{label}</button>)}
      </nav>
      <div className="sidebar-card">{user?<><span>SIGNED IN · {currentProfile?.role?.toUpperCase()??'USER'}</span><b>{user.email}</b><small>{canModerate?'Archive moderation access':'Personal match management'} · {data.matches.length} shared matches</small><button className="auth-link" onClick={()=>supabase.auth.signOut()}>Sign out</button></>:<><span>CONTRIBUTOR ACCESS</span><b>Sign in to log matches</b><input aria-label="Email address" type="email" placeholder="you@example.com" value={authEmail} onChange={e=>setAuthEmail(e.target.value)}/><button className="auth-link" disabled={!authEmail} onClick={sendMagicLink}>Email me a sign-in link</button>{authMessage&&<small>{authMessage}</small>}</>}</div>
      <button className="export" onClick={exportData}>⇩ Export archive</button>
    </aside>

    <main className="main">
      <header><div><p className="eyebrow">LEAGUE OF LEGENDS • CLASSIC ERA</p><h1>{tab==="overview"?"Command Center":tab==="players"?"Player Archive":tab==="roles"?"Role Archive":tab==="insights"?"Archive Insights":tab==="matches"?"Match History":tab==="feedback"?"Roadmap":tab==="review"?(reviewingSubmission?"Review Captured Match":"Review"):tab==="audit"?"Audit History":tab==="accounts"?"Account Management":editingMatch?`Edit Match #${editingMatch}`:"Log a Match"}</h1></div><div className="season"><span>Season archive</span><b>Summer 2026</b></div></header>

      {tab==="overview" && <>
        <section className="hero-card"><div><p>THE ARCHIVE</p><h2>WREQELODEON’S Classic story,<br/><em>one match at a time.</em></h2><span>Performances, Metrics, and memorable moments from the Rift.</span></div><div className="hero-ring"><b>{pct(stats.winRate)}</b><span>WIN RATE</span></div></section>
        <section className="stats-grid">
          <Stat label="TOTAL MATCHES" value={String(groupData.matches.length)} detail={`${stats.wins} victories recorded · group games`} />
          <Stat label="OVERALL WIN RATE" value={pct(stats.winRate)} detail={`${groupData.matches.length-stats.wins} hard-fought losses · group games`} tone="gold" />
          <Stat label="AVERAGE DURATION" value={`${Math.floor(stats.avgDuration)}:${String(Math.round(stats.avgDuration%1*60)).padStart(2,'0')}`} detail="Across group games" />
          <Stat label="AVERAGE KDA" value={num(stats.totalKda,2)} detail={`${stats.trackedPerformances} performances logged`} />
        </section>
        <section className="dashboard-grid">
          <article className="panel side-panel"><div className="panel-head"><div><p>SIDE PERFORMANCE</p><h3>Blue vs. Purple</h3></div><span>Group games</span></div>
            {['Blue','Purple'].map(side=>{const ms=groupData.matches.filter(m=>m.side===side),wr=ms.length?ms.filter(m=>m.result==='Win').length/ms.length:0;return <div className="side-row" key={side}><div className={`side-icon ${side.toLowerCase()}`}>{side[0]}</div><div><b>{side} Side</b><span>{ms.length} matches</span></div><div className="bar"><i style={{width:pct(wr)}}/></div><strong>{ms.length?pct(wr):'—'}</strong></div>})}
          </article>
          <article className="panel recent"><div className="panel-head"><div><p>RECENT GAMES</p><h3>Latest from the Rift</h3></div><button onClick={()=>setTab('matches')}>View all →</button></div>
            {data.matches.slice(-5).reverse().map(m=><button className="recent-row" key={m.id} onClick={()=>{setExpanded(m.id);setTab('matches')}}><span className={`result ${m.result.toLowerCase()}`}>{m.result[0]}</span><div><b>Match #{m.id}</b><span>{new Date(m.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} · {m.groupSize===1?'Solo':`${m.groupSize}-player group`} · {m.side} side · {m.duration.toFixed(1)} min</span></div><small>{m.notes||'No notes'}</small><i>›</i></button>)}
          </article>
        </section>
      </>}

      {tab==="players" && <>
        <div className="player-tabs" role="tablist">{data.players.map(p=><button role="tab" aria-selected={p===player} className={p===player?'active':''} onClick={()=>{setPlayer(p);setPlayerMatchScope("group");setExpandedChampion(null);setSelectedRole(null);setShowAllChampions(false);setShowAllPlayerMatches(false);setPlayerMatchPage(0)}} key={p}>{playerName(p)}</button>)}</div>
        <div className="player-scope-bar"><div><b>STATISTICS VIEW</b><span>Group games are the archive default. Solo matches are excluded from shared metrics.</span></div><div className="player-scope-toggle" role="group" aria-label="Player statistics match type">{([['group','Group games'],['solo','Solo queue'],['all','All matches']] as [PlayerMatchScope,string][]).map(([scope,label])=><button type="button" aria-pressed={playerMatchScope===scope} className={playerMatchScope===scope?'active':''} onClick={()=>{setPlayerMatchScope(scope);setExpandedChampion(null);setSelectedRole(null);setShowAllPlayerMatches(false);setPlayerMatchPage(0)}} key={scope}>{label}</button>)}</div></div>
        <section className="player-hero"><div className="avatar">{playerName(player).split(' ').map(s=>s[0]).join('')}</div><div><p>PLAYER PROFILE</p><small className="gamer-tag-label">GAMER TAG</small><h2>{playerName(player)}</h2><b className="player-real-name">{player}</b><span>{playerRows.length} recorded performances across {new Set(playerRows.map(p=>p.role)).size} roles</span></div><div className="player-kpis"><div><span>WIN RATE</span><b>{playerMatches.length?pct(playerWins/playerMatches.length):'—'}</b></div><div><span>AVG KDA</span><b>{num((playerTotals.kills+playerTotals.assists)/Math.max(1,playerTotals.deaths),2)}</b></div><div><span>MAIN ROLE</span><b>{mainRole?<RoleLabel role={mainRole}/>:'—'}</b></div></div></section>
        <section className="player-overall"><div className="panel role-summary"><div className="panel-head"><div><p>ROLE PERFORMANCE</p><h3>Overall role breakdown</h3></div></div><div className="role-summary-grid">{playerRoleStats.map(role=><article className={selectedRole===role.role?'selected':''} key={role.role}><button type="button" disabled={!role.games} aria-expanded={selectedRole===role.role} onClick={()=>setSelectedRole(selectedRole===role.role?null:role.role)}><div><b><RoleLabel role={role.role}/></b><span>{role.games} {role.games===1?'match':'matches'}</span></div><div><small>WIN RATE</small><strong>{role.games?pct(role.wins/role.games):'—'}</strong></div><div><small>MOST PLAYED</small><strong className="favorite-champion">{role.favoriteGames>0&&<img src={championIcon(role.favorite)} alt=""/>}{role.favorite}</strong>{role.favoriteGames>0&&<span>{role.favoriteGames} {role.favoriteGames===1?'game':'games'}</span>}</div><div className="role-advanced-stats"><span><small>CS</small><strong>{role.games?num(role.csPerMinute,2):'—'}</strong></span><span><small>VISION</small><strong>{role.games?num(role.visionPerMinute,2):'—'}</strong></span><span><small>KDA</small><strong>{role.games?num(role.totalKda,2):'—'}</strong></span><span className="profile-role-rating" title="Experimental feature — subject to change"><small>RATING <i>i</i></small><strong>{role.games&&role.rating!==undefined?Math.round(role.rating):'—'}</strong></span></div></button></article>)}</div></div><div className="panel role-distribution"><div className="panel-head"><div><p>ROLE DISTRIBUTION</p><h3>Matches by role</h3></div></div><div className="role-pie-wrap"><div className="role-pie" role="img" aria-label={playerRoleStats.filter(r=>r.games).map(r=>`${r.role}: ${r.games} matches`).join(', ')} style={{background:`conic-gradient(${rolePie||'#203746 0% 100%'})`}}><span><b>{playerRows.length}</b><small>MATCHES</small></span></div><div className="role-legend">{playerRoleStats.filter(r=>r.games>0).map(r=><div key={r.role}><i style={{background:roleColors[r.role]}}/><RoleLabel role={r.role}/><b>{pct(r.games/Math.max(1,playerRows.length))}</b></div>)}</div></div></div><div className="panel career-totals"><div className="panel-head"><div><p>CAREER TOTALS</p><h3>Combat record</h3></div></div><div className="career-grid"><div><span>KILLS</span><b>{playerTotals.kills}</b></div><div><span>DEATHS</span><b>{playerTotals.deaths}</b></div><div><span>ASSISTS</span><b>{playerTotals.assists}</b></div><div><span>TOTAL KDA</span><b>{num((playerTotals.kills+playerTotals.assists)/Math.max(1,playerTotals.deaths),2)}</b></div></div></div></section>
        {selectedRole&&<section className="panel role-match-panel"><div className="panel-head"><div><p>ROLE MATCH HISTORY</p><h3>{playerName(player)} · <RoleLabel role={selectedRole}/></h3></div><button type="button" onClick={()=>setSelectedRole(null)}>Close ×</button></div><div className="role-match-list champion-history-list">{selectedRoleRows.map(row=>{const match=playerData.matches.find(m=>m.id===row.matchId)!;return <button type="button" key={row.id} onClick={()=>{setExpanded(match.id);setTab('matches')}}><span className={`result ${match.result.toLowerCase()}`}>{match.result[0]}</span><div><b>Match #{match.id}</b><small>{new Date(match.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div><div><small>CHAMPION</small><b className="role-match-champion"><img src={championIcon(row.champion)} alt=""/>{row.champion}</b></div><div><small>K / D / A</small><b>{row.kills} / {row.deaths} / {row.assists}</b></div><div><small>CS · VISION</small><b>{row.cs} · {row.vision}</b></div><i>›</i></button>})}</div></section>}
        <ChampionCompletion key={`completion-${player}-${playerMatchScope}`} data={playerData} player={player} onOpenMatch={openAndFocusMatch}/>
        <PartyPerformance key={`party-${player}-${playerMatchScope}`} data={playerData} player={player} onOpenMatch={openAndFocusMatch}/>
        <section className="panel player-match-panel"><div className="panel-head"><div><p>PLAYER MATCH HISTORY</p><h3>{showAllPlayerMatches?`All ${playerMatchRows.length} ${playerName(player)} matches`:`Latest ${Math.min(5,playerMatchRows.length)} matches`}</h3></div>{playerMatchRows.length>5&&<button className="champion-pool-toggle" type="button" aria-expanded={showAllPlayerMatches} onClick={()=>{setShowAllPlayerMatches(!showAllPlayerMatches);setPlayerMatchPage(0)}}><i>{showAllPlayerMatches?'−':'+'}</i><span>{showAllPlayerMatches?'Show latest 5':'Show all '+playerMatchRows.length}</span></button>}</div><div className="player-match-list champion-history-list">{visiblePlayerMatchRows.map(row=>{const match=playerData.matches.find(m=>m.id===row.matchId)!;return <button type="button" key={row.id} onClick={()=>{setExpanded(match.id);setTab('matches')}}><span className={`result ${match.result.toLowerCase()}`}>{match.result[0]}</span><div><b>Match #{match.id}</b><small>{new Date(match.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div><div><small>CHAMPION</small><b className="role-match-champion"><img src={championIcon(row.champion)} alt=""/>{row.champion}</b></div><div><small>ROLE</small><b><RoleLabel role={row.role}/></b></div><div><small>K / D / A</small><b>{row.kills} / {row.deaths} / {row.assists}</b></div><i>›</i></button>})}</div>{showAllPlayerMatches&&playerMatchPageCount>1&&<div className="player-match-pagination"><button type="button" disabled={playerMatchPage===0} onClick={()=>setPlayerMatchPage(page=>Math.max(0,page-1))}>← Previous</button><span>Page {playerMatchPage+1} of {playerMatchPageCount}</span><button type="button" disabled={playerMatchPage>=playerMatchPageCount-1} onClick={()=>setPlayerMatchPage(page=>Math.min(playerMatchPageCount-1,page+1))}>Next →</button></div>}</section>
        <section className="panel champion-panel"><div className="panel-head"><div><p>CHAMPION POOL</p><h3>Most-played champions</h3></div>{championMap.length>8&&<button className="champion-pool-toggle" type="button" aria-expanded={showAllChampions} onClick={()=>setShowAllChampions(!showAllChampions)}><i>{showAllChampions?'−':'+'}</i><span>{showAllChampions?'Show top 8':'Show all '+championMap.length}</span></button>}</div><div className="champion-grid">{championMap.slice(0,showAllChampions?championMap.length:8).map((c,i)=>{const championRows=playerRows.filter(row=>row.champion===c.name);const recentChampionRows=[...championRows].sort((a,b)=>b.matchId-a.matchId).slice(0,10);const roleStats=Object.values(championRows.reduce((acc,row)=>{const match=data.matches.find(m=>m.id===row.matchId);const role=acc[row.role]??={name:row.role,games:0,wins:0};role.games++;role.wins+=match?.result==='Win'?1:0;return acc},{} as Record<string,{name:string;games:number;wins:number}>)).sort((a,b)=>b.games-a.games);const totalMinutes=championRows.reduce((sum,row)=>sum+(data.matches.find(m=>m.id===row.matchId)?.duration??0),0);const csPerMinute=championRows.reduce((sum,row)=>sum+row.cs,0)/Math.max(1,totalMinutes);const visionPerMinute=championRows.reduce((sum,row)=>sum+row.vision,0)/Math.max(1,totalMinutes);const isOpen=expandedChampion===c.name;return <article className={isOpen?'expanded':''} key={c.name}><button className="champion-summary" type="button" aria-expanded={isOpen} onClick={()=>setExpandedChampion(isOpen?null:c.name)}><div className="rank">{String(i+1).padStart(2,'0')}</div><div className="champion-name"><img src={championIcon(c.name)} alt=""/><span><b>{c.name}</b><small>{c.games} {c.games===1?'game':'games'}</small></span></div><strong>{pct(c.wins/c.games)}<small>WR</small></strong><em>{num(c.kda/c.games,2)} KDA</em><i>{isOpen?'−':'+'}</i></button>{isOpen&&<div className="champion-detail"><div className="role-chart"><p>ROLE BREAKDOWN</p>{roleStats.map(role=><div className="role-bar" key={role.name}><b>{role.name}</b><div aria-label={`${pct(role.wins/role.games)} wins and ${pct(1-role.wins/role.games)} losses`}><i className="role-wins" style={{width:pct(role.wins/role.games)}}/><i className="role-losses" style={{width:pct(1-role.wins/role.games)}}/></div><span>{role.games} {role.games===1?'game':'games'}</span><strong>{pct(role.wins/role.games)} WR</strong></div>)}</div><div className="champion-metrics"><div><span>AVERAGE<br/>CS / MIN</span><b>{num(csPerMinute,2)}</b></div><div><span>AVERAGE<br/>VISION / MIN</span><b>{num(visionPerMinute,2)}</b></div><div><span>AVERAGE<br/>KDA</span><b>{num(c.kda/c.games,2)}</b></div></div><div className="champion-match-history"><div className="champion-history-head"><div><p>RECENT MATCHES</p><h4>Last {recentChampionRows.length} with {c.name}</h4></div><span>Select a match to view details</span></div><div className="champion-history-list">{recentChampionRows.map(row=>{const match=data.matches.find(m=>m.id===row.matchId)!;return <button type="button" key={row.id} onClick={()=>{setExpanded(match.id);setTab('matches')}}><span className={`result ${match.result.toLowerCase()}`}>{match.result[0]}</span><div><b>Match #{match.id}</b><small>{new Date(match.date+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</small></div><div><small>ROLE</small><b>{row.role}</b></div><div><small>K / D / A</small><b>{row.kills} / {row.deaths} / {row.assists}</b></div><div><small>CS · VISION</small><b>{row.cs} · {row.vision}</b></div><i>›</i></button>})}</div></div></div>}</article>})}</div></section>
      </>}

      {tab==="roles"&&<RolesArchive data={groupData}/>}

      {tab==="insights"&&<InsightsArchive data={groupData} lifetimeData={data} onOpenMatch={openAndFocusMatch}/>}

      {tab==="matches" && <section className="panel matches-panel"><div className="match-tools"><label><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search matches or notes…"/></label><div className="match-filters"><details className="player-filter"><summary>{playerFilters.length?`${playerFilters.length} player${playerFilters.length===1?'':'s'} selected`:'All players'}<i>▾</i></summary><div className="player-filter-menu"><div><b>PLAYERS PRESENT</b>{playerFilters.length>0&&<button type="button" onClick={()=>setPlayerFilters([])}>Clear</button>}</div>{data.players.map(name=><label key={name}><input type="checkbox" checked={playerFilters.includes(name)} onChange={()=>setPlayerFilters(current=>current.includes(name)?current.filter(x=>x!==name):[...current,name])}/><span>{playerName(name)}</span></label>)}</div></details><div className="result-buttons">{['All','Win','Loss'].map(x=><button className={resultFilter===x?'active':''} onClick={()=>setResultFilter(x)} key={x}>{x}</button>)}</div></div></div>
        <div className="match-list">{filteredMatches.map(m=>{const roster=data.performances.filter(p=>p.matchId===m.id);const canManage=!!user&&(isAdmin||m.createdBy===user.id);return <article className={expanded===m.id?'expanded':''} key={m.id}><button className="match-summary" onClick={()=>setExpanded(expanded===m.id?null:m.id)}><span className={`result ${m.result.toLowerCase()}`}>{m.result[0]}</span><div><b>Match #{m.id}</b><span>{new Date(m.date+'T00:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span><span>GAME ID · {m.gameId||'Legacy record'}</span></div><div><small>SIDE</small><b>{m.side}</b></div><div><small>DURATION</small><b>{durationInput(m.duration)}</b></div><div><small>PARTY</small><b>{m.groupSize} player{m.groupSize===1?'':'s'}</b></div><i>{expanded===m.id?'−':'+'}</i></button>{expanded===m.id&&<div className="match-detail"><div className="match-detail-head"><p>“{m.notes||'No notes were recorded for this match.'}”</p>{canManage&&<div className="match-record-actions"><button onClick={()=>{setEditingMatch(m.id);setTab('add')}}>Edit match</button><button className="delete-match" onClick={()=>deleteMatch(m)}>Delete match</button></div>}</div><div className="roster">{roster.map(p=><div key={p.id}><div className="roster-icons"><img className="champion-icon" src={championIcon(p.champion)} alt=""/><img className="roster-role-icon" src={roleIcon(p.role)} alt={`${p.role} role`}/></div><div className="roster-info"><b>{playerName(p.player)}</b><span>{p.champion} · {p.role}</span></div><strong>{p.kills}/{p.deaths}/{p.assists}</strong><small>{p.cs} CS · {p.vision} vision</small></div>)}</div></div>}</article>})}</div>
      </section>}

      {tab==="feedback"&&<section className="panel feedback-panel"><div className="panel-head"><div><p>COMMUNITY DEVELOPMENT</p><h3>Feature roadmap</h3></div></div><div className="feedback-tabs" role="tablist" aria-label="Roadmap sections"><button type="button" role="tab" aria-selected={feedbackView==="submit"} className={feedbackView==="submit"?'active':''} onClick={()=>setFeedbackView("submit")}>Request Something</button><button type="button" role="tab" aria-selected={feedbackView==="requests"} className={feedbackView==="requests"?'active':''} onClick={()=>setFeedbackView("requests")}>Feature Board</button></div>{feedbackView==="submit"?(user?<form onSubmit={e=>{e.preventDefault();submitFeedback()}}><label><span>Subject</span><input type="text" maxLength={100} required value={feedbackSubject} onChange={e=>{setFeedbackSubject(e.target.value);setFeedbackStatus("")}}/><small>{feedbackSubject.length} / 100</small></label><label><span>Context</span><textarea maxLength={1000} required rows={9} value={feedbackContext} onChange={e=>{setFeedbackContext(e.target.value);setFeedbackStatus("")}}/><small>{feedbackContext.length} / 1000</small></label><div className="feedback-actions"><button type="submit" disabled={feedbackSubmitting||!feedbackSubject.trim()||!feedbackContext.trim()}>{feedbackSubmitting?'Submitting…':'Submit'}</button><button type="button" onClick={clearFeedback}>Cancel</button></div>{feedbackStatus&&<p className="feedback-status" role="status">{feedbackStatus}</p>}</form>:<div className="feedback-auth"><b>Sign in to submit feedback</b><span>Authentication is required so each submission can be associated with its contributor.</span></div>):user?<div className="feedback-board-wrap"><div className="feedback-board-head"><div><b>REQUEST BOARD</b><span>{feedbackItems.length} submitted item{feedbackItems.length===1?'':'s'}</span></div><div className="feedback-board-controls"><button type="button" aria-pressed={showDeclined} onClick={()=>setShowDeclined(value=>!value)}>{showDeclined?'Hide declined':'Show declined'}</button>{canModerate&&<small>Drag cards between lanes or use the status menu.</small>}</div></div>{feedbackLoading?<div className="feedback-board-empty">Loading requests…</div>:<div className="feedback-board">{feedbackLaneStatuses.map(status=>{const items=feedbackItems.filter(item=>item.status===status);return <section className={`feedback-lane status-${status.toLowerCase().replaceAll(' ','-')}`} key={status} onDragOver={e=>{if(canModerate)e.preventDefault()}} onDrop={e=>{if(!canModerate)return;e.preventDefault();const id=Number(e.dataTransfer.getData("text/feedback-id"));if(id)updateFeedbackStatus(id,status)}}><header><b>{status}</b><span>{items.length}</span></header><div>{items.map(item=><article draggable={canModerate} onDragStart={e=>e.dataTransfer.setData("text/feedback-id",String(item.id))} key={item.id}><h4>{item.subject}</h4><p>{item.context}</p><footer><span><b>{item.submitterEmail}</b><time dateTime={item.createdAt}>{new Date(item.createdAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</time></span>{canModerate&&<select aria-label={`Status for ${item.subject}`} value={item.status} onChange={e=>updateFeedbackStatus(item.id,e.target.value as FeedbackStatus)}>{(["Backlog","Accepted","Declined","In Progress","Review Pending","Complete","DELETED"] as FeedbackStatus[]).map(option=><option value={option} key={option}>{option}</option>)}</select>}</footer></article>)}</div></section>})}</div>}</div>:<div className="feedback-auth"><b>Sign in to view requests</b><span>Authentication is required to view submitted feedback and its current status.</span></div>}</section>}

      {tab==="review"&&user&&canModerate&&(reviewingSubmission?<AddMatch data={data} initial={pendingInitialMatch} initialPerformances={pendingInitialPerformances} onCancel={()=>setReviewingSubmission(null)} onSave={async(m,ps)=>{const revisedMatch={game_id:m.gameId,match_date:m.date,friend_group_size:m.groupSize,ally_side:m.side,result:m.result,duration_minutes:m.duration,notes:m.notes};const revisedPerformances=ps.map(({player,champion,role,kills,deaths,assists,cs,vision})=>({player,champion,role,kills,deaths,assists,cs,vision}));const {data:matchId,error}=await supabase.rpc("approve_pending_match",{target_submission_id:reviewingSubmission.id,revised_match_data:revisedMatch,revised_performance_data:revisedPerformances});if(error)throw error;await Promise.all([loadData(),loadPendingSubmissions(),loadAudit()]);setReviewingSubmission(null);setExpanded(Number(matchId));setTab('matches')}}/>:<PendingReviewQueue submissions={pendingSubmissions} onReview={setReviewingSubmission} onReject={async id=>{const {error}=await supabase.rpc("reject_pending_match",{target_submission_id:id,reason:null});if(error){window.alert(error.message);return}await loadPendingSubmissions()}}/>)}

      {tab==="audit"&&user&&canModerate&&<div className="audit-page"><div className="audit-tabs" role="tablist" aria-label="Audit views"><button type="button" role="tab" aria-selected={auditView==="changelog"} className={auditView==="changelog"?'active':''} onClick={()=>setAuditView('changelog')}>Changelog</button><button type="button" role="tab" aria-selected={auditView==="deleted"} className={auditView==="deleted"?'active':''} onClick={()=>setAuditView('deleted')}>Deleted matches <span>{deletedMatches.length}</span></button></div>{auditView==="changelog"?<AuditArchive events={auditEvents} availableMatchIds={new Set(data.matches.map(match=>match.id))} onOpenMatch={id=>{setExpanded(id);setTab('matches')}}/>:<DeletedMatchesPanel matches={deletedMatches} onRestore={restoreMatch}/>}</div>}

      {tab==="accounts"&&user&&canModerate&&<UserAccessPanel profiles={profiles} currentUserId={user.id} canManageRoles={canManageRoles} onRoleChange={async(userId,role)=>{const {error}=await supabase.rpc("set_user_role",{target_user_id:userId,new_role:role});if(error){window.alert(error.message);return}await loadProfiles(user.id);if(userId===user.id&&role!=="administrator")setTab(role==="moderator"?'accounts':'overview')}}/>}

      {tab==="add" && (user?<AddMatch data={data} initial={editingMatch?data.matches.find(m=>m.id===editingMatch):undefined} initialPerformances={editingMatch?data.performances.filter(p=>p.matchId===editingMatch):undefined} onCancel={editingMatch?()=>{setEditingMatch(null);setTab('matches')}:undefined} onSave={async(m,ps,capture)=>{const payload={game_id:m.gameId,match_date:m.date,friend_group_size:m.groupSize,ally_side:m.side,result:m.result,duration_minutes:m.duration,notes:m.notes};const performances=ps.map(({player,champion,role,kills,deaths,assists,cs,vision})=>({player,champion,role,kills,deaths,assists,cs,vision}));if(capture&&!editingMatch){const {error}=await supabase.rpc("submit_match_for_review",{match_data:payload,performance_data:performances,capture_metadata:capture.metadata,external_capture_id:capture.id});if(error)throw error;await loadPendingSubmissions();window.alert("Match submitted for moderator review.");setTab('matches');return}const {data:savedId,error}=editingMatch?await supabase.rpc("update_match_with_performances",{target_match_id:editingMatch,match_data:payload,performance_data:performances}):await supabase.rpc("create_match_with_performances",{match_data:payload,performance_data:performances});if(error)throw error;await Promise.all([loadData(),loadAudit()]);setEditingMatch(null);setTab('matches');setExpanded(Number(savedId));}}/>:<section className="panel signin-gate"><div className="crest">C</div><p>CONTRIBUTOR ACCESS</p><h2>Sign in to log a match</h2><span>We’ll send you a secure magic link—no password needed.</span><div className="gate-auth"><input aria-label="Email address" type="email" placeholder="you@example.com" value={authEmail} onChange={e=>setAuthEmail(e.target.value)}/><button disabled={!authEmail} onClick={sendMagicLink}>Email me a sign-in link</button>{authMessage&&<small>{authMessage}</small>}</div></section>)}
      <footer className="riot-notice">Classic Match Archive is not endorsed by Riot Games and does not reflect the views or opinions of Riot Games or anyone officially involved in producing or managing Riot Games properties. Riot Games and all associated properties are trademarks or registered trademarks of Riot Games, Inc.</footer>
    </main>
  </div>;
}

function AddMatch({data,initial,initialPerformances,onSave,onCancel}:{data:TrackerData,initial?:Match,initialPerformances?:Performance[],onSave:(m:Match,p:Performance[],capture?:{id:string,metadata:Record<string,unknown>})=>Promise<void>,onCancel?:()=>void}){
  const nextId=initial?.id??Math.max(...data.matches.map(m=>m.id))+1;
  const [gameId,setGameId]=useState(initial?.gameId??''); const [date,setDate]=useState(initial?.date??new Date().toISOString().slice(0,10)); const [side,setSide]=useState(initial?.side??'Blue'); const [result,setResult]=useState(initial?.result??'Win'); const [duration,setDuration]=useState(initial?durationInput(initial.duration):'0:30:00'); const [notes,setNotes]=useState(initial?.notes??'');
  const blank=()=>({player:data.players[0],champion:data.champions[0],role:data.roles[0],kills:0,deaths:0,assists:0,cs:0,vision:0});
  const [rows,setRows]=useState(initialPerformances?.length?initialPerformances.map(({player,champion,role,kills,deaths,assists,cs,vision})=>({player,champion,role,kills,deaths,assists,cs,vision})):[blank()]);
  const [saving,setSaving]=useState(false); const [saveError,setSaveError]=useState(""); const [importMessage,setImportMessage]=useState(""); const [importedCapture,setImportedCapture]=useState<{id:string,metadata:Record<string,unknown>}|undefined>();
  const update=(i:number,key:string,value:string|number)=>setRows(rs=>rs.map((r,j)=>j===i?{...r,[key]:value}:r));
  const latestMatch=[...data.matches].filter(m=>m.id!==initial?.id).sort((a,b)=>b.id-a.id)[0];
  const latestRoster=latestMatch?data.performances.filter(p=>p.matchId===latestMatch.id&&p.tracked):[];
  const loadLastRoster=()=>setRows(latestRoster.map(({player,champion,role})=>({player,champion,role,kills:0,deaths:0,assists:0,cs:0,vision:0})));
  const clearStats=()=>setRows(current=>current.map(row=>({...row,kills:0,deaths:0,assists:0,cs:0,vision:0})));
  const importMatchJson=async(file:File)=>{
    setImportMessage("");setImportedCapture(undefined);
    try{
      const document=JSON.parse(await file.text());
      if(document.schema_version!==2)throw new Error("This match.json version is not supported. Capture a new match with the updated recorder.");
      if(document.capture_metadata?.all_participants_human===false||document.participants?.some((participant:{is_bot?:boolean})=>participant.is_bot))throw new Error("AI matches cannot be imported.");
      const match=document.match_data;const imported=Array.isArray(document.performance_data)?document.performance_data:[];
      if(!match||!imported.length)throw new Error("The file does not contain a match and tracked player performances.");
      const importedGameId=String(match.game_id??'').trim();
      if(!importedGameId)throw new Error("The capture does not include a League Game ID.");
      if(data.matches.some(existing=>existing.gameId===importedGameId&&existing.id!==initial?.id))throw new Error(`Game ID ${importedGameId} already exists in Match #${data.matches.find(existing=>existing.gameId===importedGameId)?.id}.`);
      if(!['Blue','Purple'].includes(match.ally_side)||!['Win','Loss'].includes(match.result))throw new Error("The match side or result is invalid.");
      const normalized=imported.map((row:Record<string,unknown>)=>{
        const submittedPlayer=String(row.player??'').trim();
        const player=data.players.find(candidate=>candidate.localeCompare(submittedPlayer,undefined,{sensitivity:'accent'})===0||playerName(candidate).localeCompare(submittedPlayer,undefined,{sensitivity:'accent'})===0);
        const champion=String(row.champion??'');const role=String(row.role??'');
        if(!player)throw new Error(`Unknown archive player: ${submittedPlayer}`);
        if(!data.champions.includes(champion))throw new Error(`Unknown champion: ${champion}. Add it to the champion catalog first.`);
        if(!data.roles.includes(role))throw new Error(`Unknown role: ${role}`);
        return {player,champion,role,kills:Number(row.kills)||0,deaths:Number(row.deaths)||0,assists:Number(row.assists)||0,cs:Number(row.cs)||0,vision:Number(row.vision)||0};
      });
      setGameId(importedGameId);setDate(String(match.match_date));setSide(String(match.ally_side));setResult(String(match.result));setDuration(durationInput(Number(match.duration_minutes)));setNotes(String(match.notes??''));setRows(normalized);
      setImportedCapture({id:String(document.capture_metadata?.capture_id??`game-${importedGameId}`),metadata:{...(document.capture_metadata??{}),upload_source:'match.json'}});
      setImportMessage(`Loaded ${normalized.length} player performance${normalized.length===1?'':'s'} from ${file.name}. This upload will be sent to Review.`);
    }catch(error){setImportMessage(error instanceof Error?error.message:"The selected match.json could not be read.")}
  };
  const durationParts=duration.split(':').map(Number);
  const updateDurationPart=(index:number,value:number)=>{const parts=[durationParts[0]||0,durationParts[1]||0,durationParts[2]||0];parts[index]=value;setDuration(`${parts[0]}:${String(parts[1]).padStart(2,'0')}:${String(parts[2]).padStart(2,'0')}`)};
  const submit=async(e:React.FormEvent)=>{
    e.preventDefault();setSaveError("");
    const cleanGameId=gameId.trim();
    if(!cleanGameId){setSaveError("League Game ID is required.");return}
    const duplicate=data.matches.find(match=>match.gameId===cleanGameId&&match.id!==initial?.id);
    if(duplicate){setSaveError(`Game ID ${cleanGameId} already exists in Match #${duplicate.id}.`);return}
    setSaving(true);
    const [hours,minutes,seconds]=duration.split(':').map(Number);const durationMinutes=(hours*3600+minutes*60+seconds)/60;
    const match:Match={id:nextId,gameId:cleanGameId,date,side,result,duration:durationMinutes,groupSize:rows.length,notes};
    const ps=rows.map((r,i)=>({id:Date.now()+i,matchId:nextId,team:'Ally',tracked:true,...r}));
    try{await onSave(match,ps,importedCapture)}catch(err){
      const message=err instanceof Error?err.message:err&&typeof err==='object'&&'message' in err?String(err.message):"The match could not be saved.";
      setSaveError(message);setSaving(false);
    }
  };
  return <form className="add-layout quick-log" onSubmit={submit}>{!initial&&<section className="panel capture-import"><div><p>DESKTOP CAPTURE</p><h3>Import a match.json</h3><span>Load a Classic PvP capture as a draft, then review it before publishing.</span></div><label><input type="file" accept="application/json,.json" onChange={async e=>{const file=e.target.files?.[0];if(file)await importMatchJson(file);e.currentTarget.value=''}}/><b>↑ Choose match.json</b></label>{importMessage&&<small>{importMessage}</small>}</section>}<section className="panel form-panel"><div className="step"><span>01</span><div><p>QUICK LOG · MATCH DETAILS</p><h3>Set the match in a few clicks</h3></div><small>Today, Blue side, Win, and 30:00 are preselected for rapid entry.</small></div><div className="quick-match-grid"><label>Date<div className="date-shortcut"><input type="date" required value={date} onChange={e=>setDate(e.target.value)}/><button type="button" onClick={()=>setDate(new Date().toISOString().slice(0,10))}>Today</button></div></label><label className="quick-game-id">League Game ID<input required inputMode="numeric" autoComplete="off" value={gameId} onChange={e=>setGameId(e.target.value.replace(/\s/g,''))} placeholder="e.g. 5617548128"/></label><fieldset><legend>Ally side</legend><div className="quick-choice">{['Blue','Purple'].map(value=><button type="button" aria-pressed={side===value} className={side===value?'active':''} onClick={()=>setSide(value)} key={value}>{value}</button>)}</div></fieldset><fieldset><legend>Result</legend><div className="quick-choice result-choice">{['Win','Loss'].map(value=><button type="button" aria-pressed={result===value} className={`${result===value?'active ':''}${value.toLowerCase()}`} onClick={()=>setResult(value)} key={value}>{value}</button>)}</div></fieldset><label>Duration<div className="duration-selects"><span><select aria-label="Duration hours" value={durationParts[0]||0} onChange={e=>updateDurationPart(0,Number(e.target.value))}>{Array.from({length:3},(_,value)=><option value={value} key={value}>{value}</option>)}</select><small>HOURS</small></span><i>:</i><span><select aria-label="Duration minutes" value={durationParts[1]||0} onChange={e=>updateDurationPart(1,Number(e.target.value))}>{Array.from({length:61},(_,value)=><option value={value} key={value}>{String(value).padStart(2,'0')}</option>)}</select><small>MINUTES</small></span><i>:</i><span><select aria-label="Duration seconds" value={durationParts[2]||0} onChange={e=>updateDurationPart(2,Number(e.target.value))}>{Array.from({length:61},(_,value)=><option value={value} key={value}>{String(value).padStart(2,'0')}</option>)}</select><small>SECONDS</small></span></div></label><label className="quick-notes">Notes <span>optional</span><input value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Memorable moment or context…"/></label></div></section>
    <section className="panel form-panel"><div className="step quick-roster-head"><span>02</span><div><p>QUICK LOG · PARTY PERFORMANCE</p><h3>Enter the scoreboard</h3></div><small>Tab moves across fields. Numeric values select automatically when focused.</small><div className="roster-actions">{latestRoster.length>0&&!initial&&<button type="button" onClick={loadLastRoster}>↻ Load Match #{latestMatch.id} roster</button>}<button type="button" onClick={clearStats}>Clear stats</button></div></div><div className="quick-column-head" aria-hidden="true"><span>#</span><span>PLAYER</span><span>CHAMPION</span><span>ROLE</span><span>K</span><span>D</span><span>A</span><span>CS</span><span>VISION</span><span></span></div>{rows.map((r,i)=><div className="performance-form" key={i}><b>{String(i+1).padStart(2,'0')}</b><label><span>Player</span><select aria-label={`Player ${i+1}`} value={r.player} onChange={e=>update(i,'player',e.target.value)}>{data.players.map(x=><option value={x} key={x}>{playerName(x)}</option>)}</select></label><label><span>Champion</span><div className="champion-select"><img src={championIcon(r.champion)} alt=""/><select aria-label={`Champion for player ${i+1}`} value={r.champion} onChange={e=>update(i,'champion',e.target.value)}>{data.champions.map(x=><option key={x}>{x}</option>)}</select></div></label><label><span>Role</span><select aria-label={`Role for player ${i+1}`} value={r.role} onChange={e=>update(i,'role',e.target.value)}>{data.roles.map(x=><option key={x}>{x}</option>)}</select></label>{(['kills','deaths','assists','cs','vision'] as const).map(k=><label className="quick-stat" key={k}><span>{k.toUpperCase()}</span><input aria-label={`${k} for player ${i+1}`} min="0" inputMode="numeric" type="number" value={r[k]} onFocus={e=>e.currentTarget.select()} onChange={e=>update(i,k,Number(e.target.value))}/></label>)}{rows.length>1?<button aria-label={`Remove player ${i+1}`} type="button" className="remove" onClick={()=>setRows(rs=>rs.filter((_,j)=>j!==i))}>×</button>:<span/>}</div>)}<div className="quick-roster-footer"><button type="button" className="add-player" onClick={()=>setRows(rs=>[...rs,blank()])}>＋ Add player</button><span>{rows.length} player{rows.length===1?'':'s'} · {rows.reduce((sum,row)=>sum+row.kills,0)} kills · {rows.reduce((sum,row)=>sum+row.assists,0)} assists</span></div></section>
    <div className="save-bar"><div><span>{initial?'EDITING':'NEW'} MATCH #{nextId}</span><b>{saveError||`${rows.length} performance${rows.length===1?'':'s'} ready to save`}</b></div><div className="save-actions">{onCancel&&<button className="cancel-edit" type="button" onClick={onCancel}>Cancel</button>}<button type="submit" disabled={saving}>{saving?'Saving…':initial?'Save changes →':'Save to archive →'}</button></div></div></form>
}
